(4509,'jwj4w','HTML','<p>Women aged 25 to 49 years of age are invited for cervical screening every three years, and women age 50 to 64 years are invited every five years. The risk of developing cervical cancer can be significantly reduced by having regular screening.</p>\n\n<p>If you do not want to be called for future cervical smears, please complete this form and the practice will send you instructions regarding how to submit a NHS Cervical Screening Programme Decline. By declining, you will not receive any further invitations to be screened for cervical cancer or any further information about the NHS Cervical Screening Programme.</p>','html','','',73,0,'a:45:{s:8:\"calc_dec\";s:0:\"\";s:6:\"maxnum\";i:10;s:9:\"show_hide\";s:4:\"show\";s:7:\"autocom\";i:0;s:8:\"hide_opt\";a:1:{i:0;s:28:\"Cervical Screening Programme\";}s:5:\"blank\";s:0:\"\";s:8:\"multiple\";i:0;s:5:\"label\";s:0:\"\";s:4:\"size\";s:0:\"\";s:9:\"read_only\";i:0;s:6:\"unique\";i:0;s:10:\"unique_msg\";s:26:\"This value must be unique.\";s:10:\"in_section\";i:4506;s:6:\"minnum\";i:1;s:7:\"invalid\";s:0:\"\";s:15:\"hide_field_cond\";a:1:{i:0;s:2:\"==\";}s:5:\"other\";i:0;s:5:\"slide\";s:0:\"\";s:4:\"calc\";s:0:\"\";s:8:\"conf_msg\";s:31:\"The entered values do not match\";s:14:\"separate_value\";i:0;s:10:\"admin_only\";i:0;s:6:\"format\";s:0:\"\";s:3:\"max\";s:0:\"\";s:12:\"repeat_limit\";s:0:\"\";s:4:\"step\";i:1;s:14:\"clear_on_focus\";i:0;s:7:\"any_all\";s:3:\"any\";s:10:\"hide_field\";a:1:{i:0;i:4305;}s:11:\"placeholder\";s:0:\"\";s:6:\"repeat\";s:0:\"\";s:9:\"calc_type\";s:0:\"\";s:11:\"custom_html\";s:92:\"<div id=\\\"frm_field_[id]_container\\\" class=\\\"frm_form_field form-field\\\">[description]</div>\";s:10:\"conf_input\";s:0:\"\";s:5:\"align\";s:5:\"block\";s:18:\"required_indicator\";s:1:\"*\";s:11:\"form_select\";s:0:\"\";s:7:\"classes\";s:0:\"\";s:17:\"dyn_default_value\";s:0:\"\";s:9:\"conf_desc\";s:0:\"\";s:10:\"conf_field\";s:0:\"\";s:10:\"post_field\";s:0:\"\";s:12:\"custom_field\";