(5139,'3mda6','HTML','<h4>Patient instructions</h4>\r\n<ul>\r\n<li>In the morning, ensure that you are rested and have taken no exercise in the last 30 minutes.</li>\r\n<li>Then sit in a chair comfortably upright with your arm supported on a table beside you, with both feet on the ground.</li>\r\n<li>Put the cuff on your upper arm (5cm above your elbow) resting on the table, the cuff should be roughly at the level of your heart.</li>\r\n<li>Press the on/start button on the BP monitor and take two readings at least 1 minute apart.</li>\r\n<li>Record the readings below with your pulse rate and any comments.</li>\r\n<li>Repeat that evening and for a total of 7 days using alternate arms.</li>\r\n</ul>','html','','',62,0,'a:58:{s:8:\"calc_dec\";s:0:\"\";s:6:\"maxnum\";i:10;s:10:\"hide_field\";a:0:{}s:6:\"repeat\";s:0:\"\";s:8:\"hide_opt\";a:0:{}s:5:\"blank\";s:0:\"\";s:8:\"multiple\";i:0;s:5:\"label\";s:0:\"\";s:7:\"autocom\";i:0;s:4:\"size\";s:0:\"\";s:9:\"read_only\";i:0;s:6:\"unique\";i:0;s:10:\"unique_msg\";s:26:\"This value must be unique.\";s:10:\"in_section\";s:4:\"5130\";s:5:\"slide\";s:0:\"\";s:7:\"invalid\";s:0:\"\";s:15:\"hide_field_cond\";a:1:{i:0;s:2:\"==\";}s:5:\"other\";i:0;s:4:\"calc\";s:0:\"\";s:8:\"conf_msg\";s:31:\"The entered values do not match\";s:14:\"separate_value\";i:0;s:10:\"admin_only\";a:1:{i:0;s:0:\"\";}s:11:\"form_select\";s:0:\"\";s:6:\"format\";s:0:\"\";s:3:\"max\";s:0:\"\";s:12:\"repeat_limit\";s:0:\"\";s:4:\"step\";i:1;s:14:\"clear_on_focus\";i:0;s:7:\"any_all\";s:3:\"any\";s:9:\"show_hide\";s:4:\"show\";s:11:\"placeholder\";s:0:\"\";s:9:\"calc_type\";s:0:\"\";s:11:\"custom_html\";s:88:\"<div id=\"frm_field_[id]_container\" class=\"frm_form_field form-field\">[description]</div>\";s:10:\"conf_input\";s:0:\"\";s:5:\"align\";s:5:\"block\";s:18:\"required_indicator\";s:1:\"*\";s:6:\"minnum\";i:1;s:7:\"classes\";s:9:\"hide-item\";s:17:\"dyn_default_value\";s:0:\"\";s:9:\"conf_desc\";s:0:\"\";s:10:\"conf_field\";s:0:\"\";s:12:\"custom_field\