(6827,'p2hr8','HTML','<p>Before you continue, you need to read and agree to the following statements.</p>\r\n<ul>\r\n    <li>I have read and understood the information and things to consider about online services</li>\r\n    <li>I will be responsible for the security of the information that I see or download</li>\r\n    <li>If I choose to share my information with anyone else, this is at my own risk</li>\r\n    <li>If I suspect that my account has been accessed by someone without my agreement, I will contact the surgery as soon as possible</li>\r\n    <li>If I see information in my record that is not about me or is inaccurate, I will contact the surgery as soon as possible</li>\r\n    <li>If I think that I may come under pressure to give access to someone else unwillingly, I will contact the surgery as soon as possible</li>\r\n</ul>','html','','',9,0,'a:55:{s:5:\"align\";s:5:\"block\";s:11:\"form_select\";s:0:\"\";s:9:\"show_hide\";s:4:\"show\";s:7:\"any_all\";s:3:\"any\";s:10:\"hide_field\";a:0:{}s:15:\"hide_field_cond\";a:1:{i:0;s:2:\"==\";}s:8:\"hide_opt\";a:0:{}s:10:\"post_field\";s:0:\"\";s:12:\"custom_field\";s:0:\"\";s:8:\"taxonomy\";s:8:\"category\";s:11:\"exclude_cat\";i:0;s:9:\"read_only\";i:0;s:12:\"autocomplete\";s:0:\"\";s:10:\"admin_only\";a:1:{i:0;s:0:\"\";}s:6:\"unique\";i:0;s:10:\"unique_msg\";s:26:\"This value must be unique.\";s:4:\"calc\";s:0:\"\";s:8:\"calc_dec\";s:0:\"\";s:9:\"calc_type\";s:0:\"\";s:11:\"is_currency\";i:0;s:15:\"custom_currency\";i:0;s:25:\"custom_thousand_separator\";s:1:\",\";s:24:\"custom_decimal_separator\";s:1:\".\";s:15:\"custom_decimals\";i:2;s:18:\"custom_symbol_left\";s:0:\"\";s:19:\"custom_symbol_right\";s:0:\"\";s:17:\"dyn_default_value\";s:0:\"\";s:8:\"multiple\";i:0;s:7:\"autocom\";i:0;s:10:\"conf_field\";s:0:\"\";s:10:\"conf_input\";s:0:\"\";s:9:\"conf_desc\";s:0:\"\";s:8:\"conf_msg\";s:31:\"The entered values do not match\";s:5:\"other\";i:0;s:10:\"in_section\";s:1:\"0\";s:7:\"prepend\";s:0:\"\";s:6:\"append\";s: