(7202,'utvjoi2','How would you rate your level of breathlessness?','','radio','','a:5:{i:0;a:3:{s:5:\"label\";s:45:\"I only get breathless with strenuous exercise\";s:5:\"value\";s:45:\"I only get breathless with strenuous exercise\";s:5:\"image\";s:1:\"0\";}i:1;a:3:{s:5:\"label\";s:79:\"I get short of breath when hurrying on level ground or walking up a slight hill\";s:5:\"value\";s:79:\"I get short of breath when hurrying on level ground or walking up a slight hill\";s:5:\"image\";s:1:\"0\";}i:2;a:3:{s:5:\"label\";s:149:\"On level ground, I walk slower than people of my age because of breathlessness, or I have to stop for breath when walking at my own pace on the level\";s:5:\"value\";s:149:\"On level ground, I walk slower than people of my age because of breathlessness, or I have to stop for breath when walking at my own pace on the level\";s:5:\"image\";s:1:\"0\";}i:3;a:3:{s:5:\"label\";s:86:\"I stop for breath after walking about 100 yards or after a few minutes on level ground\";s:5:\"value\";s:86:\"I stop for breath after walking about 100 yards or after a few minutes on level ground\";s:5:\"image\";s:1:\"0\";}i:4;a:3:{s:5:\"label\";s:82:\"I am too breathless to leave the house or I am breathless when dressing/undressing\";s:5:\"value\";s:82:\"I am too breathless to leave the house or I am breathless when dressing/undressing\";s:5:\"image\";s:1:\"0\";}}',7,1,'a:81:{s:8:\"calc_dec\";s:0:\"\";s:6:\"maxnum\";i:10;s:6:\"locale\";s:0:\"\";s:9:\"show_hide\";s:4:\"show\";s:8:\"restrict\";i:0;s:6:\"repeat\";i:0;s:8:\"hide_opt\";a:0:{}s:10:\"in_section\";i:7201;s:5:\"blank\";s:27:\"This field cannot be blank.\";s:15:\"hide_field_cond\";a:1:{i:0;s:2:\"==\";}s:18:\"required_indicator\";s:1:\"*\";s:7:\"autocom\";i:0;s:4:\"size\";s:0:\"\";s:9:\"read_only\";i:0;s:6:\"unique\";i:0;s:5:\"clock\";i:12;s:8:\"end_year\";i:2020;s:8:\"use_calc\";i:0;s:5:\"slide\";i:0;s:7:\"invalid\";s:0:\"\";s:5:\"label\";s:0:\"\";s:6:\"attach\";b:0;s:12:\"remove_label\";s:6:\"Remove\";s:10:\"adm