(21729,'sp_ack_email_default_51','{\"subject\":\"Hypothyroid Self Assessment - [PRACTICE]\",\"body\":\"Dear [PATIENT],<p>Thank you for submitting a Hypothyroid Self Assessment.We will contact you if an appointment or telephone consultation is necessary.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21730,'sp_ack_email_default_41','{\"subject\":\"Long Term Conditions Synchronisation - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Long Term Condition Synchronisation request.<p>We will reply to you as soon as possible via email. We will try to respond to all queries within 2 working days. Please note that this service is not for urgent medical enquiries. <p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21731,'sp_ack_email_default_39','{\"subject\":\"Medical Report Request - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a medical report request.<p>We will reply to you as soon as possible via email. We aim to respond to all queries within 2 working days.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21732,'sp_ack_email_default_42','{\"subject\":\"Medication Review - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Medication Review.<p>We will contact you if an appointment or telephone consultation is necessary.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21733,'sp_ack_email_default_14','{\"subject\":\"New Patient Registration - [PRACTICE]\",\"body\":\"Dear [PATIENT],<p>Thank you for registering as a patient. You will now need to come into the practice with proof of identity to complete your registration.<p><p><em>[PRACTICE]<\\/em>\"}','no'),
(21734,'sp_ack_email_default_47','{\"subject\":\"Oxford Hip Score - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting an Oxford Hip Score.<p>We will contact you if an appointment or telephone consultation is necessary.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21735,'sp_ack_email_default_46','{\"subject\":\"Oxford Knee Score - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting an Oxford Knee Score.<p>We will contact you if an appointment or telephone consultation is necessary.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21736,'sp_ack_email_default_37','{\"subject\":\"Patient Health Questionnaire (PHQ-9) - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Patient Health Questionnaire (PHQ-9).<p>We will contact you if an appointment or telephone consultation is necessary.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21737,'sp_ack_email_default_9','{\"subject\":\"Patient Participation Group Registration - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for registering your interest in joining our Patient Participation Group. <p>We will be in contact soon with more information. We will try to respond to all queries within 2 working days.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21738,'sp_ack_email_default_20','{\"subject\":\"Prescription Question - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a question about your prescription.<p>We will reply to you as soon as possible via email. We will try to respond to all queries within 2 working days. Please note that this service is not for urgent medical enquiries. <p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21739,'sp_ack_email_default_21','{\"subject\":\"Prescription Synchronisation - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a question about your prescription synchronisation.<p>We will reply to you as soon as possible via email. We will try to respond to all queries within 2 working days. Please note that this service is not for urgent medical enquiries. <p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21740,'sp_ack_email_default_32','{\"subject\":\"Referral Request - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a referral request.<p>We will reply to you as soon as possible via email. We aim to respond to all queries within 2 working days.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21741,'sp_ack_email_default_24','{\"subject\":\"Register a Carer - [PRACTICE]\",\"body\":\"Dear [PATIENT],<p>Thank you for registering as a carer, we will update your records accordingly.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21742,'sp_ack_email_default_17','{\"subject\":\"Register for Online Services - [PRACTICE]\",\"body\":\"Dear [PATIENT],<p>Thank you for registering for online services. Now that you have completed this form you will need to present yourself at the practice  with photographic proof of ID e.g. passport or driving licence. A member of our reception team will then present you with your username and password.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21743,'sp_ack_email_default_48','{\"subject\":\"Register for the Electronic Prescription Service - [PRACTICE]\",\"body\":\"Dear [PATIENT],<p>Thank you for registering for the Electronic Prescription Service. The next time you order a repeat prescription it will be sent electronically to your chosen pharmacy. Please allow 2 working days before collecting your prescription.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21744,'sp_ack_email_default_16','{\"subject\":\"Repeat Prescription Request - [PRACTICE]\",\"body\":\"Dear [PATIENT],<p>Thank you for requesting a repeat prescription. Please allow 2 working days for your prescription to be ready at your requested pharmacy.<p>In future you may wish to\\u00a0register for online services to have the ability to Book or Cancel an Appointment, Request a Repeat Prescription, Change Personal Details and View your Medical Records without visiting the practice.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21745,'sp_ack_email_default_25','{\"subject\":\"Sick \\/ Fit Note Request - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a sick \\/ fit note request form.<p>We will reply to you as soon as possible via email. We will try to respond to all queries within 2 working days. <p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21746,'sp_ack_email_default_38','{\"subject\":\"Smoking Review - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Smoking Review.<p>We will contact you if an appointment or telephone consultation is necessary.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21747,'sp_ack_email_default_15','{\"subject\":\"Summary Care Record opt out - [PRACTICE]\",\"body\":\"Dear [PATIENT],<p>Thank you for opting out of your Summary Care Record.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21748,'sp_ack_email_default_23','{\"subject\":\"Test Results Request - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a test results request form.<p>We will reply to you as soon as possible via email. We aim to respond to all queries within 2 working days.<p><strong>When the test results will be available<\\/strong><p>Approximate number of working days for tests ordered at surgery:<p>Blood Tests \\u2013 5 working days unless otherwise advised<br>X-Ray \\u2013 2 weeks<br>Urine Test \\u2013 5 working days<br>Biopsy \\u2013 8 weeks<br>Smear Test \\u2013 8 weeks<p>In future you may wish to\\u00a0register for online services to have the ability to Book or Cancel an Appointment, Request a Repeat Prescription, Change Personal Details and View your Medical Records without visiting the practice.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21749,'sp_ack_email_default_31','{\"subject\":\"Track a Referral - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a track a referral form.<p>We will reply to you as soon as possible via email. We aim to respond to all queries within 2 working days.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21750,'sp_ack_email_default_10','{\"subject\":\"Travel Risk Assessment - [PRACTICE]\",\"body\":\"Dear [PATIENT],<p>Thank you for submitting a Travel Risk Assessment form.<p><p>You will now need to book two consecutive appointments (i.e. two appointments together) with a Practice Nurse in order to have your vaccinations administered for your trip.<p>Please also bring your Travel Vaccination Record to your appointment if you have one.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
(21751,'sp_ack_email_default_34','{\"subject\":\"Urinary Tract (LUTS) Review - [PRACTICE]\",\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Urinary Tract (LUTS) Review.<p>We will contact you if an appointment or telephone consultation is necessary.<p><strong><em>[PRACTICE]<\\/em><\\/strong>\"}','no'),
