(22997,'sp_form_reply_options_10_footfallv6','[[\"up to date\",\"Dear [PATIENT],\\r\\n\\r\\nYour vaccinations are up-to-date for this destination. Please check though for general advice on one of the travel websites, e.g. www.masta-travel-health.com\\r\\n\\r\\n[PRACTICE]\"],[\"late requests\",\"Dear [PATIENT],\\r\\n\\r\\nYour vaccinations need to start as soon as possible to be effective in time and we are unable to provide this service to you within this timeframe. Please make an appointment as soon as possible with a local private provider. E.g. Masta Travel Clinic.\\r\\n\\r\\n[PRACTICE]\"]]','no'),
(22998,'sp_form_reply_options_31_footfallv6','[[\"contact directly\",\"Dear [PATIENT],\\r\\n\\r\\nUnfortunately we are unable to track this referral on your behalf please contact the provider\\/department directly.\\r\\n\\r\\n[PRACTICE]\"]]','no'),
(22999,'sp_form_reply_options_23_footfallv6','[[\"normal\",\"Dear [PATIENT],\\r\\n\\r\\nYour test results have been looked at by a doctor and found to be normal. In future you can check your test results on .....\\r\\n\\r\\n[PRACTICE]\"],[\"satisfactory\",\"Dear [PATIENT],\\r\\n\\r\\nYour test results were satisfactory. No further action required.\\r\\n\\r\\n[PRACTICE]\"],[\"make app.\",\"Dear [PATIENT],\\r\\n\\r\\nYour test results are now back. Please make an appointment with your Doctor to discuss the results.\\r\\n\\r\\n[PRACTICE]\"],[\"call asap\",\"Dear [PATIENT],\\r\\n\\r\\nYour test results are now available and we would like to you call your Doctor to discuss the results as soon as possible.\\r\\n\\r\\n[PRACTICE]\"]]','no'),
