(23001,'sp_form_reply_options_16_footfallv6','[[\"processed\",\"Dear [PATIENT],\\r\\n\\r\\nYour repeat prescription has been accepted and processed. Thank you.\\r\\n\\r\\n[PRACTICE]\"],[\"items unavailable\",\"Dear [PATIENT],\\r\\n\\r\\nSome of the items you requested are not in stock and will need to be ordered. We will contact you when your prescription is ready for collection.\\r\\n\\r\\n[PRACTICE]\"],[\"make app.\",\"Dear [PATIENT],\\r\\n\\r\\nUnfortunately none of the items in your request can be repeated without a visit to the doctor. Please make an appointment with your GP.\\r\\n\\r\\n[PRACTICE]\"]]','no'),
(23002,'sp_form_reply_options_17_footfallv6','[[\"bring ID to practice\",\"Dear [PATIENT],\\r\\n\\r\\nTo complete your registration you will need to visit the practice with two forms of ID (e.g. passport, driving license, utility bill).\\r\\n\\r\\nYou will then be issued with a username and password.\\r\\n\\r\\n[PRACTICE]\"]]','no'),
