\"wplc_pro_sst2\";s:32:\"Connecting. Please be patient...\";s:13:\"wplc_pro_tst1\";s:34:\"Reactivating your previous chat...\";s:14:\"wplc_pro_intro\";s:56:\"Hello. Please input your details so that I may help you.\";s:15:\"wplc_user_enter\";s:32:\"Press ENTER to send your message\";s:20:\"wplc_text_chat_ended\";s:40:\"The chat has been ended by the operator.\";s:16:\"wplc_welcome_msg\";s:84:\"Please standby for an agent. While you wait for the agent you may type your message.\";s:10:\"wplc_theme\";s:7:\"theme-2\";s:13:\"wplc_newtheme\";s:7:\"theme-2\";s:24:\"wplc_elem_trigger_action\";s:1:\"0\";s:22:\"wplc_elem_trigger_type\";s:1:\"0\";s:20:\"wplc_elem_trigger_id\";s:0:\"\";s:14:\"wplc_show_date\";s:1:\"0\";s:14:\"wplc_show_time\";s:1:\"0\";s:14:\"wplc_show_name\";s:1:\"0\";s:16:\"wplc_show_avatar\";s:1:\"1\";s:20:\"wplc_use_node_server\";s:1:\"1\";s:26:\"wplc_new_chat_ringer_count\";i:5;s:17:\"wplc_gdpr_enabled\";s:1:\"1\";s:24:\"wplc_gdpr_notice_company\";s:17:\"FootFall Template\";s:34:\"wplc_gdpr_notice_retention_purpose\";s:12:\"Chat/Support\";s:33:\"wplc_gdpr_notice_retention_period\";s:2:\"30\";s:19:\"wplc_user_no_answer\";s:43:\"There is No Answer. Please Try Again Later.\";s:13:\"wplc_pro_fst3\";s:15:\"Start live chat\";s:22:\"wplc_user_welcome_chat\";s:28:\"Welcome. How may I help you?\";s:19:\"wplc_close_btn_text\";s:5:\"close\";}','yes'),
