(25211,'WPLC_ET_SETTINGS','a:6:{s:23:\"wplc_enable_transcripts\";s:1:\"1\";s:24:\"wplc_send_transcripts_to\";s:4:\"user\";s:36:\"wplc_send_transcripts_when_chat_ends\";i:0;s:20:\"wplc_et_email_header\";s:285:\"&lt;a title=\\&quot;FootFall Template\\&quot; href=\\&quot;http://footfallv6.siliconpreview.co.uk\\&quot; style=\\&quot;font-family: Arial, Helvetica, sans-serif; font-size: 13px; color: #FFF; font-weight: bold; text-decoration: underline;\\&quot;&gt;FootFall Template&lt;/a&gt;         \";s:20:\"wplc_et_email_footer\";s:475:\"&lt;span style=\\&#039;font-family: Arial, Helvetica, sans-serif; font-size: 13px; color: #FFF; font-weight: normal;\\&#039;&gt;Thank you for chatting with us. If you have any questions, please &lt;a href=\\&quot;mailto:abigail.hewlett@siliconpractice.co.uk\\&quot; target=\\&quot;_blank\\&quot; style=\\&quot;font-family: Arial, Helvetica, sans-serif; font-size: 13px; color: #FFF; font-weight: bold; text-decoration: underline;\\&quot;&gt;contact us&lt;/a&gt;&lt;/span&gt;         \";s:18:\"wplc_et_email_body\";s:2933:\"&lt;!DOCTYPE HTML PUBLIC \\&quot;-//W3C//DTD HTML 4.01 Transitional//EN\\&quot; \\&quot;http://www.w3.org/TR/html4/loose.dtd\\&quot;&gt;		\r\n	&lt;html&gt;\r\n	\r\n	&lt;body&gt;\r\n\r\n\r\n\r\n		&lt;table id=\\&quot;\\&quot; border=\\&quot;0\\&quot; cellpadding=\\&quot;0\\&quot; cellspacing=\\&quot;0\\&quot; width=\\&quot;100%\\&quot; style=\\&quot;background-color: #ec822c;\\&quot;&gt;\r\n	    &lt;tbody&gt;\r\n	      &lt;tr&gt;\r\n	        &lt;td width=\\&quot;100%\\&quot; style=\\&quot;padding: 30px 20px 100px 20px;\\&quot;&gt;\r\n	          &lt;table align=\\&quot;center\\&quot; cellpadding=\\&quot;0\\&quot; cellspacing=\\&quot;0\\&quot; class=\\&quot;\\&quot; width=\\&quot;100%\\&quot; style=\\&quot;border-collapse: separate; max-width:600px;\\&quot;&gt;\r\n	            &lt;tbody&gt;\r\n	              &lt;tr&gt;\r\n	                &lt;td style=\\&quot;text-align: center; padding-bottom: 20px;\\&quot;&gt;\r\n	                  \r\n	                  &lt;p&gt;[wplc_et_transcript_header_text]&lt;/p&gt;\r\n	                &lt;/td&gt;\r\n	              &lt;/tr&gt;\r\n	            &lt;/tbody&gt;\r\n	          &lt;/table&gt;\r\n\r\n	          &lt;table id=\\&quot;\\&quot; align=\\&quot;center\\&quot; cellpadding=\\&quot;0\\&quot; cellspacing=\\&quot;0\\&quot; class=\\&quot;\\&quot; width=\\&quot;100%\\&quot; style=\\&quot;border-collapse: separate; max-width: 600px; font-family: Georgia, serif; font-size: 12px; color: rgb(51, 62, 72); border: 0px solid rgb(255, 255, 255); border-radius: 10px; background-color: rgb(255, 255, 255);\\&quot;&gt;\r\n	          &lt;tbody&gt;\r\n	              &lt;tr&gt;\r\n	                &lt;td class=\\&quot;sortable-list ui-sortable\\&quot; style=\\&quot;padding:20px;\\&quot;&gt;\r\n	                    [wplc_et_transcript]\r\n	                &lt;/td&gt;\r\n	              &lt;/tr&gt;\r\n	            &lt;/tbody&gt;\r\n	          &lt;/table&gt;\r\n\r\n	          &lt;table align=\\&quot;center\\&quot; cellpadding=\\&quot;0\\&quot; cellspacing=\\&quot;0\\&quot; class=\\&quot;\\&quot; width=\\&quot;100%\\&quot; style=\\&quot;border-collapse: separate; max-width:100%;\\&quot;&gt;\r\n	            &lt;tbody&gt;\r\n	              &lt;tr&gt;\r\n	                &lt;td style=\\&quot;padding:20px;\\&quot;&gt;\r\n	                  &lt;table border=\\&quot;0\\&quot; cellpadding=\\&quot;0\\&quot; cellspacing=\\&quot;0\\&quot; class=\\&quot;\\&quot; width=\\&quot;100%\\&quot;&gt;\r\n	                    &lt;tbody&gt;\r\n	                      &lt;tr&gt;\r\n	                        &lt;td id=\\&quot;\\&quot; align=\\&quot;center\\&quot;&gt;\r\n	                         &lt;p&gt;[wplc_et_transcript_footer_text]&lt;/p&gt;\r\n	                        &lt;/td&gt;\r\n	                      &lt;/tr&gt;\r\n	                    &lt;/tbody&gt;\r\n	                  &lt;/table&gt;\r\n	                &lt;/td&gt;\r\n	              &lt;/tr&gt;\r\n	            &lt;/tbody&gt;\r\n	          &lt;/table&gt;\r\n	        &lt;/td&gt;\r\n	      &lt;/tr&gt;\r\n	    &lt;/tbody&gt;\r\n	  &lt;/table&gt;\r\n\r\n\r\n		\r\n		&lt;/div&gt;\r\n	&lt;/body&gt;\r\n&lt;/html&gt;\r\n			         \";}','yes'),
