(25220,'WPLC_AUTO_RESPONDER_SETTINGS','a:4:{s:17:\"wplc_ar_from_name\";s:17:\"FootFall Template\";s:18:\"wplc_ar_from_email\";s:37:\"abigail.hewlett@siliconpractice.co.uk\";s:15:\"wplc_ar_subject\";s:54:\"Thank you for inquiry. We will get back to you shortly\";s:12:\"wplc_ar_body\";s:203:\"	    &lt;p&gt;Hi {wplc-user-name}&lt;/p&gt;\r\n	    &lt;p&gt;Thank you for getting in touch with us.&lt;/p&gt;\r\n	    &lt;p&gt;Your email has been received. We will get back to you shortly.&lt;/p&gt;\r\n	    \";}','yes'),
