(3946642,'sp_ack_email_footfallv6_73','{\"body\":\"Dear [PATIENT],<p>Thank you for submitting your Get help for any health problem form.<p>Your problem will be managed by one of our team.<p>We aim to respond within 4 working hours. <p>[PRACTICE]\",\"subject\":\"Get help for any health problem\"}','yes'),
(3946848,'sp_ack_email_footfallv6_43','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting a question to the practice. <p>We will try to respond to all queries within 2 working days. Please note that this service is not for urgent medical enquiries. <p>[PRACTICE]\",\"subject\":\"Ask a question\"}','yes'),
(3946849,'sp_ack_email_footfallv6_18','{\"body\":\"Dear [PATIENT],<p>Thank you for cancelling your appointment.<p>In future you may wish to\\u00a0register for online services to have the ability to book or cancel an appointment, request a repeat prescription, change your personal details and view your medical records without visiting the surgery.<p>[PRACTICE]\",\"subject\":\"Cancel appointment\"}','yes'),
(3946850,'sp_ack_email_footfallv6_36','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting an Epilepsy review.<p>We will contact you if an appointment or telephone consultation is necessary.<p>[PRACTICE]\",\"subject\":\"Epilepsy review\"}','yes'),
(3946851,'sp_ack_email_footfallv6_53','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting an Epworth sleepiness scale.<p>We will contact you if an appointment or telephone consultation is necessary.<p>[PRACTICE]\",\"subject\":\"Epworth sleepiness scale\"}','yes'),
(3946852,'sp_ack_email_footfallv6_11','{\"body\":\"Dear [PATIENT],<p>Thank you for submitting your Feedback form. <p>We will try to respond to all queries within 2 working days. Please note that this service is not for urgent medical enquiries. <p>[PRACTICE]\",\"subject\":\"Feedback\"}','yes'),
(3946853,'sp_ack_email_footfallv6_145','{\"body\":\"Dear [PATIENT],<p>Thank you for submitting your Urgent appointment request.<p>Your request will be managed by one of our team.<p>We aim to respond within 4 working hours. <p>[PRACTICE]\",\"subject\":\"Urgent appointment request\"}','yes'),
(3946854,'sp_ack_email_footfallv6_51','{\"body\":\"Dear [PATIENT],<p>Thank you for submitting a Hypothyroidism review.<p>We will contact you if an appointment or telephone consultation is necessary.<p>[PRACTICE]\",\"subject\":\"Hypothyroidism review\"}','yes'),
(3946855,'sp_ack_email_footfallv6_64','{\"body\":\"Dear [PATIENT],<p>Thank you for submitting a Long term conditions synchronisation request.<p>We will try to respond to all queries within 2 working days. Please note that this service is not for urgent medical enquiries.<p>[PRACTICE]\",\"subject\":\"Long term conditions synchronisation\"}','yes'),
(3946856,'sp_ack_email_footfallv6_39','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Medical report request.<p>We aim to respond to all queries within 2 working days.<p>[PRACTICE]\",\"subject\":\"Medical report request\"}','yes'),
(3946857,'sp_ack_email_footfallv6_48','{\"body\":\"Dear [PATIENT],<p>Thank you for nominating a pharmacy.<p>The next time you order a repeat prescription it will be sent electronically to your chosen pharmacy.<p>[PRACTICE]\",\"subject\":\"Nominate a pharmacy\"}','yes'),
(3946858,'sp_ack_email_footfallv6_47','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting an Oxford hip score.<p>We will contact you if an appointment or telephone consultation is necessary.<p>[PRACTICE]\",\"subject\":\"Oxford hip score\"}','yes'),
(3946859,'sp_ack_email_footfallv6_52','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting an Oxford knee score.<p>We will contact you if an appointment or telephone consultation is necessary.<p>[PRACTICE]\",\"subject\":\"Oxford knee score\"}','yes'),
(3946860,'sp_ack_email_footfallv6_37','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Patient Health Questionnaire (PHQ-9).<p>We will contact you if an appointment or telephone consultation is necessary.<p>[PRACTICE]\",\"subject\":\"Patient Health Questionnaire (PHQ-9)\"}','yes'),
(3946861,'sp_ack_email_footfallv6_9','{\"body\":\"Dear [PATIENT], <p>Thank you for registering your interest in joining our Patient Participation Group. <p>We will be in contact soon with more information.<p>[PRACTICE]\",\"subject\":\"Patient Participation Group registration\"}','yes'),
(3946862,'sp_ack_email_footfallv6_20','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting a question about your prescription.<p>We will try to respond to all queries within 2 working days. Please note that this service is not for urgent medical enquiries. <p>[PRACTICE]\",\"subject\":\"Prescription question\"}','yes'),
(3946863,'sp_ack_email_footfallv6_21','{\"body\":\"Dear [PATIENT], <p>Thank you for requesting to synchronise your prescriptions.<p>We will try to respond to all queries within 2 working days. Please note that this service is not for urgent medical enquiries. <p>[PRACTICE]\",\"subject\":\"Prescription synchronisation\"}','yes'),
(3946864,'sp_ack_email_footfallv6_32','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Referral request.<p>We aim to respond to all queries within 2 working days.<p>[PRACTICE]\",\"subject\":\"Referral request\"}','yes'),
(3946865,'sp_ack_email_footfallv6_24','{\"body\":\"Dear [PATIENT],<p>Thank you for registering as a carer, we will update your records accordingly.<p>[PRACTICE]\",\"subject\":\"Register a carer\"}','yes'),
(3946866,'sp_ack_email_footfallv6_16','{\"body\":\"Dear [PATIENT],<p>Thank you for requesting a repeat prescription.<p>Please allow 2 working days for your prescription to be ready collect.<p>In future you may wish to\\u00a0register for online services to have the ability to book or cancel an appointment, request a repeat prescription, change your personal details and view your medical records without visiting the surgery.<p>[PRACTICE]\",\"subject\":\"Repeat prescription request\"}','yes'),
(3946867,'sp_ack_email_footfallv6_25','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting a sick (fit) note request.<p>We will try to respond to all queries within 2 working days. <p>[PRACTICE]\",\"subject\":\"Sick note request\"}','yes'),
(3946868,'sp_ack_email_footfallv6_15','{\"body\":\"Dear [PATIENT],<p>Thank you for your request. You have now opted out of your Summary Care Record.<p>[PRACTICE]\",\"subject\":\"Summary Care Record opt out\"}','yes'),
(3946869,'sp_ack_email_footfallv6_23','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Test results request.<p>We aim to respond to all queries within 2 working days.<p>In future you may wish to\\u00a0register for online services to have the ability to book or cancel an appointment, request a repeat prescription, change your personal details and view your medical records without visiting the surgery.<p>[PRACTICE]\",\"subject\":\"Test results request\"}','yes'),
(3946870,'sp_ack_email_footfallv6_31','{\"body\":\"Dear [PATIENT], <p>Thank you for submitting a Track a referral form.<p>We aim to respond to all queries within 2 working days.<p>[PRACTICE]\",\"subject\":\"Track a referral\"}','yes'),
(3946871,'sp_ack_email_footfallv6_10','{\"body\":\"Dear [PATIENT],<p>Thank you for submitting a Travel risk assessment.<p>You will now need to book 2 consecutive appointments with a practice nurse in order to have your vaccinations administered for your trip.<p>Please also bring your travel vaccination record to your appointment if you have one.<p>[PRACTICE]\",\"subject\":\"Travel risk assessment\"}','yes'),
