ily: \\\"Poppins\\\", sans-serif;\\n\\tmargin-top: 0;\\n\\tfont-weight: 600;\\n\\tcolor: #2b2350;\\n}\\n.nhsuk-card {\\n\\t-webkit-box-shadow: 0 10px 20px 0 rgba(14, 3, 52, 0.1);\\n\\tbox-shadow: 0 10px 20px 0 rgba(14, 3, 52, 0.1);\\n\\tbackground: #fff;\\n\\tborder-radius: 15px;\\n\\tpadding: 0px;\\n\\t-webkit-transition: all 0.3s ease-in-out;\\n\\t-o-transition: all 0.3s ease-in-out;\\n\\ttransition: all 0.3s ease-in-out;\\n\\tbackground-color: #fff;\\n}\\n\\n\\n.nhsuk-card {\\n  display: block;\\n  position: relative;\\n  max-width: 400px;\\n  background-color: #fff;\\n  text-decoration: none;\\n  z-index: 0;\\n  overflow: hidden;\\n\\n\\n  &:before {\\n    content: \\\"\\\";\\n    position: absolute;\\n    z-index: -1;\\n    top: -32px;\\n    right: -32px;\\n    background: #005eb8;\\n    height: 32px;\\n    width: 32px;\\n    border-radius: 32px;\\n    transform: scale(1);\\n    transform-origin: 50% 50%;\\n    transition: transform 0.45s ease-out;\\n  }\\n\\n  &:hover:before {\\n    transform: scale(26);\\n  }\\n}\\n\\n.nhsuk-card:hover {\\n  p {\\n    transition: all 0.3s ease-out;\\n    color: rgba(255, 255, 255, 0.8);\\n  };\\n  h2 {\\n    transition: all 0.3s ease-out;\\n    color: #ffffff !important;\\n  };\\na {\\n    transition: all 0.3s ease-out;\\n    color: #ffffff !important;\\n  }\\n}\\n.wp-block-nhsuk-section .nhs-blue .nhsuk-card:hover a {\\n    color: #fff!important;\\n}\\n.wp-block-nhsuk-section .nhs-blue .nhsuk-card a {\\n    color: #000!important;\\n}\\n\\n.nhsuk-header__link {\\nbackground: url( https:\\/\\/demo.siliconpractice.in\\/wp-content\\/uploads\\/2024\\/07\\/clinic-logo.png) no-repeat;\\n}\\n.nhsuk-header__logo svg {\\ndisplay:none;\\n}\\n.nhsuk-header__link .nhsuk-u-padding-left-3 {\\npadding:10px 10px 10px 59px !important;\\n}\\n\\n.nhs-blue .nhsuk-grid-column-one-third {\\nwidth: 16.66%;\\npadding: 0 5px;\\n}\\n\\n.nhs-blue .nhsuk-card__content {\\n padding: 5px 12px 30px 12px !important;\\n}\\n\\n\\n.nhs-blue h3, .nhsuk-heading-m {\\nfont-size: 1.1rem !important;\\nline-height: 1.2 !important;\\ntext-align: center;\\n}\\n\\n\\n.nhs-blue p{\\nfont-size: 0.9rem !important;\\ntext-align: center;\\n}\\n\\n.boxsets .nhsuk-card-group {\\n    margin-top: -170px !important;\\n}\\n\\n.nhs-blue .nhsuk-card {\\n    background-color: #eefdff !important;\\ncolor: #000!important;\\n}\\n\\n.nhsuk-width-container {\\n    max-width: 1100px !important;\\n}\\n\\n\\n.boxsets .nhsuk-card__img{\\n    border-bottom: 0px solid\\n}\\n\\n.nhsuk-breadcrumb__link:visited {\\n    color: #005eb8 !important;\\n}\\n.nhsuk-breadcrumb {\\n    background-color: #d8dde0 !important;\\n}\\n\\n.app-list-signage li a .nhsuk-icon{\\nheight: 40px!important;\\n}\\n\\n.metaslider .caption-wrap {\\nopacity:1.0;\\n}\",\"color\":{\"background\":\"var(--wp--preset--color--color_nhsuk-dark-pink)\",\"text\":\"var(--wp--preset--color--color_nhsuk-warm-yellow)\"},\"elements\":{\"heading\":{\"color\":{\"text\":\"var(--wp--preset--color--color_nhsuk-green)\"}},\"link\":{\"color\":{\"text\":\"var(--wp--preset--color--color_nhsuk-warm-yellow)\"}}},\"typography\":{\"textTransform\":\"none\"}},\"isGlobalStylesUserThemeJSON\":true,\"version\":2}','Custom Styles','','publish','closed','closed','','wp-global-styles-nhsuk-frontend-theme','','','2025-06-04 11:36:52','2025-06-04 06:06:52','',0,'https://footfallformsuite.foundationpreview.co.uk/2023/05/03/wp-global-styles-nhsuk-frontend-theme/',0,'wp_global_styles','',0),
(359,1,'2023-05-09 17:50:34','2023-05-09 16:50:34','<!-- wp:nhsuk/care-card {\"heading\":\"Call 108 or go to Emergency ward now for any of these:\",\"level\":\"emergency\"} -->\n<div class=\"nhsuk-card nhsuk-card--care nhsuk-card--care--emergency\"><div class=\"nhsuk-card--care__heading-container\"><h2 class=\"nhsuk-card--care__heading\">Call 108 or go to Emergency ward now for any of these:</h2><span class=\"nhsuk-card--care__arrow\" aria-hidden=\"true\"></span></div><div class=\"nhsuk-card__content\"><!-- wp:paragraph -->\n<p><strong>Signs of a heart attack</strong><br>chest pain, pressure, heaviness, tightness or squeezing across the chest</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Signs of a stroke&nbsp;</strong><br>face dropping on one side, canâ€™t hold both arms up, difficulty speaking</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Sudden confusion (delirium)&nbsp;</strong><br>cannot be sure of own name or age</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Suicide attempt&nbsp;</strong><br>by taking something or self-harming</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Severe difficulty breathing&nbsp;</strong><br>not being able to get words out, choking or gasping</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Heavy bleeding&nbsp;</strong><br>spraying, pouring or enough to make a puddle</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Severe injuries&nbsp;</strong><br>after a serious accident</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Seizure (fit)&nbsp;</strong><br>shaking or jerking because of a fit, or unconscious (canâ€™t be woken up)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Sudden, rapid swelling&nbsp;</strong><br>of the lips, mouth, throat or tongue</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:nhsuk/care-card -->','Check it\'s not an emergency','','publish','closed','closed','','check-its-not-an-emergency','','','2024-04-29 22:56:02','2024-04-29 17:26:02','',0,'https://footfallformsuite.foundationpreview.co.uk/2023/05/09/check-its-not-an-emergency/',0,'wp_block','',0),
(360,1,'2023-05-09 17:55:46','2023-05-09 16:55:46','<!-- wp:nhsuk/care-card {\"heading\":\"Call 999 or go to A\\u0026amp;E now if:\",\"level\":\"emergency\"} -->\n<div class=\"nhsuk-card nhsuk-card--care nhsuk-card--care--emergency\"><div class=\"nhsuk-card--care__heading-container\"><h2 class=\"nhsuk-card--care__heading\">Call 999 or go to A&amp;E now if:</h2><span class=\"nhsuk-card--care__arrow\" aria-hidden=\"true\"></span></div><div class=\"nhsuk-card__content\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>someone\'s life is at risk - for example they have seriously injured themselves or taken an overdose</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>you do not feel you can keep yourself or someone else safe</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>A mental health emergency should be taken as seriously as a medical emergency. If you are having a mental health crisis or are considering self-harm, please seek help immediately.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"tel:999\">Call: 999</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"https://www.nhs.uk/service-search/find-an-accident-and-emergency-service\">Find your nearest A&amp;E</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:nhsuk/care-card -->','Check it\'s not a mental health emergency','','publish','closed','closed','','check-its-not-a-mental-health-emergency','','','2023-08-25 14:00:35','2023-08-25 13:00:35','',0,'https://footfallformsuite.foundationpreview.co.uk/2023/05/09/check-its-not-a-mental-health-emergency/',0,'wp_block','',0),
(663,1,'2023-05-16 16:16:57','2023-05-16 15:16:57','<!-- wp:nhsuk/hero {\"heading\":\"Welcome\",\"text\":\"Tagline\"} -->\n<section class=\"nhsuk-hero nhsuk-hero--image nhsuk-hero--image-description\" style=\"background-image:url(https://footfallformsuite.foundationpreview.co.uk/wp-content/plugins/nhsukblocks/src/images/nhs-hero-placeholder.jpg)\"><div class=\"nhsuk-width-container\"><div class=\"nhsuk-grid-row\"><div class=\"nhsuk-grid-column-two-thirds\"><div class=\"nhsuk-hero-content\"><h1 class=\"nhsuk-u-margin-bottom-3\">Welcome</h1><p class=\"nhsuk-body-l nhsuk-u-margin-bottom-0\">Tagline</p><span class=\"nhsuk-hero__arrow\" aria-hidden=\"true\"></span></div></div></div></div></section>\n<!-- /wp:nhsuk/hero -->\n\n<!-- wp:nhsuk/section {\"className\":\"nhsuk-u-padding-top-9\",\"backgroundColor\":\"color_nhsuk-white\"} -->\n<section class=\"wp-block-nhsuk-section nhsuk-u-padding-top-3 nhsuk-u-padding-bottom-3 nhsuk-u-padding-top-9 has-color-nhsuk-white-background-color has-background\" style=\"background-image:url(undefined);background-position:center right;background-repeat:no-repeat;background-size:cover\"><!-- wp:nhsuk/container {\"className\":\"nhsuk-u-padding-top-6\"} -->\n<div class=\"wp-block-nhsuk-container nhsuk-width-container nhsuk-u-padding-top-6\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Health A to Z</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Your complete guide to conditions, symptoms and treatments, including what to do and when to get help.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:nhsuk/action-link {\"text\":\"Go to the Health A to Z\",\"url\":\"https://www.nhs.uk/conditions/\"} -->\n<div class=\"wp-block-nhsuk-action-link nhsuk-action-link\"><a class=\"nhsuk-action-link__link\" href=\"https://www.nhs.uk/conditions/\"><svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\" class=\"nhsuk-icon nhsuk-icon__arrow-right-circle\" aria-hidden=\"true\"><path d=\"M0 0h24v24H0z\" fill=\"none\"></path><path d=\"M12 2a10 10 0 0 0-9.95 9h11.64L9.74 7.05a1 1 0 0 1 1.41-1.41l5.66 5.65a1 1 0 0 1 0 1.42l-5.66 5.65a1 1 0 0 1-1.41 0 1 1 0 0 1 0-1.41L13.69 13H2.05A10 10 0 1 0 12 2z\"></path></svg><span class=\"nhsuk-action-link__text\">Go to the Health A to Z</span></a></div>\n<!-- /wp:nhsuk/action-link --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">New patients</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We are currently accepting new NHS patients, find out about registering with the surgery.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:nhsuk/action-link {\"text\":\"Register with the surgery\",\"url\":\"/services/new-patients/\"} -->\n<div class=\"wp-block-nhsuk-action-link nhsuk-action-link\"><a class=\"nhsuk-action-link__link\" href=\"/services/new-patients/\"><svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\" class=\"nhsuk-icon nhsuk-icon__arrow-right-circle\" aria-hidden=\"true\"><path d=\"M0 0h24v24H0z\" fill=\"none\"></path><path d=\"M12 2a10 10 0 0 0-9.95 9h11.64L9.74 7.05a1 1 0 0 1 1.41-1.41l5.66 5.65a1 1 0 0 1 0 1.42l-5.66 5.65a1 1 0 0 1-1.41 0 1 1 0 0 1 0-1.41L13.69 13H2.05A10 10 0 1 0 12 2z\"></path></svg><span class=\"nhsuk-action-link__text\">Register with the surgery</span></a></div>\n<!-- /wp:nhsuk/action-link --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:nhsuk/container --></section>\n<!-- /wp:nhsuk/section -->','Homepage: NHS Hero','','publish','closed','closed','','nhs-hero-and-2-column-2','','','2023-08-11 16:01:16','2023-08-11 15:01:16','',0,'https://footfallformsuite.foundationpreview.co.uk/2023/05/16/nhs-hero-and-2-column-2/',0,'wp_block','',0),
(666,1,'2023-05-17 10:33:56','2023-05-17 09:33:56','<!-- wp:nhsuk/section {\"verticleSpacing\":7,\"backgroundColor\":\"color_nhsuk-white\"} -->\n<section class=\"wp-block-nhsuk-section nhsuk-u-padding-top-7 nhsuk-u-padding-bottom-7 has-color-nhsuk-white-background-color has-background\" style=\"background-image:url(undefined);background-position:center right;background-repeat:no-repeat;background-size:cover\"><!-- wp:nhsuk/container -->\n<div class=\"wp-block-nhsuk-container nhsuk-width-container\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Follow us on social media</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Keep up to date on our social media for surgery announcements, advice and news.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:nhsuk/signage -->\n<ul class=\"wp-block-nhsuk-signage app-list-signage app-list-signage--two-columns\"><!-- wp:nhsuk/signage-item {\"content\":\"Facebook\",\"url\":\"#\"} -->\n<li><a href=\"#\"><svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\" class=\"nhsuk-icon nhsuk-icon__chevron-right\" aria-hidden=\"true\"><path d=\"M15.5 12a1 1 0 0 1-.29.71l-5 5a1 1 0 0 1-1.42-1.42l4.3-4.29-4.3-4.29a1 1 0 0 1 1.42-1.42l5 5a1 1 0 0 1 .29.71z\"></path></svg>Facebook</a></li>\n<!-- /wp:nhsuk/signage-item -->\n\n<!-- wp:nhsuk/signage-item {\"content\":\"Twitter\"} /-->\n\n<!-- wp:nhsuk/signage-item {\"content\":\"Instagram\"} /--></ul>\n<!-- /wp:nhsuk/signage --></div>\n<!-- /wp:nhsuk/container --></section>\n<!-- /wp:nhsuk/section -->','Homepage: Social Media','','publish','closed','closed','','homepage-social-media','','','2023-09-20 12:01:23','2023-09-20 11:01:23','',0,'https://footfallformsuite.foundationpreview.co.uk/2023/05/17/homepage-social-media/',0,'wp_block','',0),
