(2458,1,'2024-03-27 17:01:29','2024-03-27 17:01:29','<!-- wp:paragraph -->\n<p>Use this service to do something.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You can use this service if you:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>are registered at the surgery</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Before you start</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We\'ll ask you for:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>your first and last name, date of birth, sex, postcode, email and phone number</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>if applicable, the details of the person you are completing the form on behalf of</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:nhsuk/button {\"text\":\"Start now\"} -->\n<a class=\"nhsuk-button nhsuk-button--primary\" role=\"button\">Start now</a>\n<!-- /wp:nhsuk/button -->\n\n<!-- wp:paragraph -->\n<p>You can also phone us on [siteinfo field=phone].</p>\n<!-- /wp:paragraph -->','Start page','','inherit','closed','closed','','886-revision-v1','','','2024-03-27 17:01:29','2024-03-27 17:01:29','',886,'https://footfallformsuite.foundationpreview.co.uk/?p=2458',0,'revision','',0),
