(2536,1,'2024-04-29 22:55:45','2024-04-29 17:25:45','<!-- wp:nhsuk/care-card {\"heading\":\"Call 108 or go to Emergency ward now for any of these:\",\"level\":\"emergency\"} -->\n<div class=\"nhsuk-card nhsuk-card--care nhsuk-card--care--emergency\"><div class=\"nhsuk-card--care__heading-container\"><h2 class=\"nhsuk-card--care__heading\">Call 108 or go to Emergency ward now for any of these:</h2><span class=\"nhsuk-card--care__arrow\" aria-hidden=\"true\"></span></div><div class=\"nhsuk-card__content\"><!-- wp:paragraph -->\n<p><strong>Signs of a heart attack</strong><br>chest pain, pressure, heaviness, tightness or squeezing across the chest</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Signs of a stroke&nbsp;</strong><br>face dropping on one side, canâ€™t hold both arms up, difficulty speaking</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Sudden confusion (delirium)&nbsp;</strong><br>cannot be sure of own name or age</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Suicide attempt&nbsp;</strong><br>by taking something or self-harming</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Severe difficulty breathing&nbsp;</strong><br>not being able to get words out, choking or gasping</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Heavy bleeding&nbsp;</strong><br>spraying, pouring or enough to make a puddle</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Severe injuries&nbsp;</strong><br>after a serious accident</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Seizure (fit)&nbsp;</strong><br>shaking or jerking because of a fit, or unconscious (canâ€™t be woken up)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Sudden, rapid swelling&nbsp;</strong><br>of the lips, mouth, throat or tongue</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:nhsuk/care-card -->','Check it\'s not an emergency','','inherit','closed','closed','','359-revision-v1','','','2024-04-29 22:55:45','2024-04-29 17:25:45','',359,'https://demo.siliconpractice.in/?p=2536',0,'revision','',0),
