(3013,1,'2025-06-04 11:30:59','2025-06-04 06:00:59','{\"styles\":{\"css\":\".nhsuk-header--organisation .nhsuk-header__navigation {\\n    margin-top: 10px!important;\\n}\\n\\n\\n.nhsuk-breadcrumb {\\n    background-color: #005eb8 !important;\\n}\\n.nhsuk-breadcrumb__link:visited {\\n    color: #fff !important;\\n}\\n\\n.wp-block-nhsuk-section {\\n\\tbackground-color: #fff !important;\\n}\\n\\n.nhsuk-icon {\\n    float: left;\\n\\ttop: 3px !important;\\n}\\n.nhsuk-action-link__link .nhsuk-icon__arrow-right-circle {\\n\\tfill: #005eb8 !important;\\n}\\n\\n\\n\\n.nhsuk-header__container {\\n    padding: 20px 0 0 0 !important;\\n}\\n.nhsuk-u-padding-top-7 {\\n\\tpadding-top: 10px !important;\\n}\\n\\n.home .nhsuk-footer-content {\\n    display:none !important;\\n}\\n\\n.home .nhsuk-footer {\\n        max-height: 84px;\\n    }\\n\\n.nhsuk-footer a:visited {\\n    color: #005eb8 !important;\\n}\\n\\nbody {\\n\\tfont-family: \\\"Poppins\\\", sans-serif;\\n\\tfont-size: 16px;\\n\\tline-height: 28px;\\n\\tcolor: #797687;\\n\\toverflow-x: hidden;\\n}\\n\\nsvg {\\n\\tdisplay: block;\\n}\\n\\na,\\nbutton,\\ninput,\\ntextarea,\\nbutton,\\nselect {\\n\\t-webkit-transition: all 0.3s ease-in-out;\\n\\t-o-transition: all 0.3s ease-in-out;\\n\\ttransition: all 0.3s ease-in-out;\\n}\\n\\nbutton {\\n\\tcursor: pointer;\\n\\toutline: 0;\\n}\\n\\ninput,\\ntextarea,\\nselect,\\n.form-control {\\n\\twidth: 100%;\\n\\tpadding: 10px 12px;\\n\\toutline: 0;\\n}\\n\\n.form-control {\\n\\tbackground: #fdfafa;\\n\\tpadding: 15px 30px;\\n\\tborder: 1px solid #efe7e7;\\n\\tmargin-bottom: 30px;\\n\\tborder-radius: 30px;\\n\\theight: 60px;\\n}\\n\\n.form-control:focus {\\n\\t-webkit-box-shadow: none;\\n\\tbox-shadow: none;\\n\\tborder-color: #efe7e7;\\n\\tbackground: #fff;\\n\\t-webkit-box-shadow: 0px 20px 40px 0px rgba(79, 35, 35, 0.1);\\n\\tbox-shadow: 0px 20px 40px 0px rgba(79, 35, 35, 0.1);\\n}\\n\\na,\\na:hover {\\n\\ttext-decoration: none;\\n}\\n\\nh1,\\nh2,\\nh3,\\nh4,\\nh5,\\nh6 {\\n\\tfont-family: \\\"Poppins\\\", sans-serif;\\n\\tmargin-top: 0;\\n\\tfont-weight: 600;\\n\\tcolor: #2b2350;\\n}\\n.nhsuk-card {\\n\\t-webkit-box-shadow: 0 10px 20px 0 rgba(14, 3, 52, 0.1);\\n\\tbox-shadow: 0 10px 20px 0 rgba(14, 3, 52, 0.1);\\n\\tbackground: #fff;\\n\\tborder-radius: 15px;\\n\\tpadding: 0px;\\n\\t-webkit-transition: all 0.3s ease-in-out;\\n\\t-o-transition: all 0.3s ease-in-out;\\n\\ttransition: all 0.3s ease-in-out;\\n\\tbackground-color: #fff;\\n}\\n\\n\\n.nhsuk-card {\\n  display: block;\\n  position: relative;\\n  max-width: 400px;\\n  background-color: #fff;\\n  text-decoration: none;\\n  z-index: 0;\\n  overflow: hidden;\\n\\n\\n  &:before {\\n    content: \\\"\\\";\\n    position: absolute;\\n    z-index: -1;\\n    top: -32px;\\n    right: -32px;\\n    background: #005eb8;\\n    height: 32px;\\n    width: 32px;\\n    border-radius: 32px;\\n    transform: scale(1);\\n    transform-origin: 50% 50%;\\n    transition: transform 0.45s ease-out;\\n  }\\n\\n  &:hover:before {\\n    transform: scale(26);\\n  }\\n}\\n\\n.nhsuk-card:hover {\\n  p {\\n    transition: all 0.3s ease-out;\\n    color: rgba(255, 255, 255, 0.8);\\n  };\\n  h2 {\\n    transition: all 0.3s ease-out;\\n    color: #ffffff !important;\\n  };\\na {\\n    transition: all 0.3s ease-out;\\n    color: #ffffff !important;\\n  }\\n}\\n.wp-block-nhsuk-section .nhs-blue .nhsuk-card:hover a {\\n    color: #fff!important;\\n}\\n.wp-block-nhsuk-section .nhs-blue .nhsuk-card a {\\n    color: #000!important;\\n}\\n\\n.nhsuk-header__link {\\nbackground: url( https:\\/\\/demo.siliconpractice.in\\/wp-content\\/uploads\\/2024\\/07\\/clinic-logo.png) no-repeat;\\n}\\n.nhsuk-header__logo svg {\\ndisplay:none;\\n}\\n.nhsuk-header__link .nhsuk-u-padding-left-3 {\\npadding:10px 10px 10px 59px !important;\\n}\\n\\n.nhs-blue .nhsuk-grid-column-one-third {\\nwidth: 16.66%;\\npadding: 0 5px;\\n}\\n\\n.nhs-blue .nhsuk-card__content {\\n padding: 5px 12px 30px 12px !important;\\n}\\n\\n\\n.nhs-blue h3, .nhsuk-heading-m {\\nfont-size: 1.1rem !important;\\nline-height: 1.2 !important;\\ntext-align: center;\\n}\\n\\n\\n.nhs-blue p{\\nfont-size: 0.9rem !important;\\ntext-align: center;\\n}\\n\\n.boxsets .nhsuk-card-group {\\n    margin-top: -170px !important;\\n}\\n\\n.nhs-blue .nhsuk-card {\\n    background-color: #eefdff !important;\\ncolor: #000!important;\\n}\\n\\n.nhsuk-width-container {\\n    max-width: 1100px !important;\\n}\\n\\n\\n.boxsets .nhsuk-card__img{\\n    border-bottom: 0px solid\\n}\\n\\n.nhsuk-breadcrumb__link:visited {\\n    color: #005eb8 !important;\\n}\\n.nhsuk-breadcrumb {\\n    background-color: #d8dde0 !important;\\n}\\n\\n.app-list-signage li a .nhsuk-icon{\\nheight: 40px!important;\\n}\\n\\n.metaslider .caption-wrap {\\nopacity:1.0;\\n}\",\"color\":{\"background\":\"var:preset|color|color_nhsuk-dark-pink\",\"text\":\"var:preset|color|color_nhsuk-warm-yellow\"},\"elements\":{\"heading\":{\"color\":{\"text\":\"var:preset|color|color_nhsuk-green\"}},\"link\":{\"color\":{\"text\":\"var:preset|color|color_nhsuk-warm-yellow\"}}}},\"isGlobalStylesUserThemeJSON\":true,\"version\":2}','Custom Styles','','inherit','closed','closed','','30-revision-v1','','','2025-06-04 11:30:59','2025-06-04 06:00:59','',30,'https://demo.siliconpractice.in/?p=3013',0,'revision','',0),
