INSERT INTO `footfallv6_sp_formtemplate` VALUES
(1,145,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_145_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_6838_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\"></h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_6840_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">About the problem</h3>\r\n\r\n\r\n<div id=\"frm_field_6841_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container preview_answer\">\r\n    <div class=\"frm_label frm_primary_label\">Tell us about the problem\r\n        \r\n    </div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_xzd2s2\">It may help to describe the problem as if you were speaking to someone</div>\r\n    <div class=\'textarea\' style=\'min-height:94px\'>[6841]</div>\r\n    \r\n</div>\n<div id=\"frm_field_6842_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">How long has this been a problem?\r\n        \r\n    </div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_ku3zc2\">It\'s helpful to tell us whether it\'s been days, weeks, months or years</div>\r\n    <div class=\'input text\'>[6842]</div>\r\n    \r\n</div>\n<div id=\"frm_field_6843_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Do you have an idea about what is causing the problem?\r\n        \r\n    </div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_9d20r2\">This might be something that happened or that you discovered around the time your symptoms began</div>\r\n    <div class=\'textarea\' style=\'min-height:43px\'>[6843]</div>\r\n    \r\n</div>\n<div id=\"frm_field_6844_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Can you think of anything that is worrying you about the problem?\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:43px\'>[6844]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6845_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Is there a member of staff who would be best to deal with this problem?\r\n        \r\n    </div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_j0ch52\">We cannot guarantee this as it depends on their availability</div>\r\n    <div class=\'input text\'>[6845]</div>\r\n    \r\n</div>\n</div>\n<div id=\"frm_field_6847_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div  id=\"field_f87al2_label\" class=\"frm_primary_label\">Upload a photograph or document\r\n        \r\n    </div>\r\n    \n\n<div class=\"frm_dropzone frm_single_upload frm_clearfix\" id=\"file6847_dropzone\" role=\"group\" >\n	<div class=\"fallback\">\n		<div class=\'input\'></div>\n				<div class=\"frm_clearfix \"></div>\n	</div>\n	<div class=\"dz-message needsclick\">\n		<span class=\"frm_icon_font frm_upload_icon\"></span>\n		<span class=\"frm_upload_text\"><button type=\"button\">Drop a file here or click to upload</button></span>\n		<span class=\"frm_compact_text\"><button type=\"button\">Choose File</button></span>\n		<div class=\"frm_small_text\">\n			Maximum upload size: 20.97MB		</div>\n	</div>\n</div>\n\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6848_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container vertical_radio\">\r\n    <div  id=\"field_3hrkb2_label\" class=\"frm_primary_label\">How would you prefer to be contacted?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_3hrkb2_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_6848-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6848]=Email].png\'><div class=\"frm_label\">		 Email</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6848-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6848]=Phone].png\'><div class=\"frm_label\">		 Phone</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6848-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6848]=Text message].png\'><div class=\"frm_label\">		 Text message</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6848-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6848]=Video call].png\'><div class=\"frm_label\">		 Video call</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6849_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Are there any times when you cannot be contacted?\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:43px\'>[6849]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6850_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container vertical_radio\">\r\n    <div  id=\"field_gi3kn2_label\" class=\"frm_primary_label\">Terms and conditions\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_gi3kn2_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_6850-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[6850]=confirmtermsandconditions].png\'><div class=\"frm_label\"> I confirm that this is not an emergency and understand the surgery cannot help while it is closed. If I need help right now, I will use the NHS 111 service. In an emergency, I will call 999 or go to A&amp;E.</div></div>\n</div>\r\n    \r\n    \r\n</div>\n    </div>\r\n    \r\n  </div>\r\n<div class=\"hide\">[frm-conditions]null[/frm-conditions]</div>'),
(2,132,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_132_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_6785_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Section</h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_6099_container\" class=\"frm_form_field frm_section_heading form-field  frm_hide_section\">\r\n<h3 class=\"frm_pos_none frm_section_spacing\">Alcohol consumption</h3>\r\n\r\n\r\n<div id=\"frm_field_6102_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<h4>This is one unit of alcohol:</h4>\n<div style=\"margin:15px 0px 15px 0px; text-align:center;\"><img style= \"width:100%; height:auto;\" src=\'/wp-content/uploads/2019/06/alcohol-units-new-IW.jpg\' alt=\"Amount of different types of drink representing one unit of alcohol\" class=\"alcohol1\"></div>\n<h4>And each one of these, is more than one unit:</h4>\n<div style=\"margin:15px 0px 15px 0px; text-align:center;\"><img style= \"width:100%; height:auto;\" src=\'/wp-content/uploads/2019/06/alcohol-units-new-IW-2.jpg\' alt=\"Amount of different types of drink representing more than one unit of alcohol\" class=\"alcohol2\"></div>\n</div>\n<div id=\"frm_field_6105_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_half vertical_radio\">\r\n    <div  id=\"field_nkhxlk2_label\" class=\"frm_primary_label\">How often do you have a drink containing alcohol?\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_nkhxlk2_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_6105-6099-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6105]=Never - 0].png\'><div class=\"frm_label\">		 Never</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6105-6099-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6105]=Monthly or less - 1].png\'><div class=\"frm_label\">		 Monthly or less</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6105-6099-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6105]=2-4 times per month - 2].png\'><div class=\"frm_label\">		 2-4 times per month</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6105-6099-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6105]=2-3 times per week - 3].png\'><div class=\"frm_label\">		 2-3 times per week</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6105-6099-4\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6105]=4+ times per week - 4].png\'><div class=\"frm_label\">		 4+ times per week</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6108_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_half vertical_radio\">\r\n    <div  id=\"field_96ukml2_label\" class=\"frm_primary_label\">How many units of alcohol do you drink on a typical day when you are drinking?\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_96ukml2_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_6108-6099-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6108]=1-2 - 0].png\'><div class=\"frm_label\">		 1-2</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6108-6099-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6108]=3-4 - 1].png\'><div class=\"frm_label\">		 3-4</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6108-6099-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6108]=5-6 - 2].png\'><div class=\"frm_label\">		 5-6</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6108-6099-3\"><img class=\'radio\' src=\'/wp-content/plugins/spFo