_label\">		 10 to 19</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_2739-2730-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2739]=20to39].png\'><div class=\"frm_label\">		 20 to 39</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_2739-2730-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2739]=40more].png\'><div class=\"frm_label\">		 40 or more</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2742_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Rollups - How many grams of tobacco did you smoke per week?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2742]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2745_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Pipe - How many grams of tobacco did you smoke per week?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2745]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2748_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">When did you quit smoking?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2748]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_2754_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Activity levels</h3>\r\n\r\n\r\n<div id=\"frm_field_2757_container\" class=\"frm_form_field form-field  frm_top_container vertical_radio\">\r\n    <div  id=\"field_zeci43_label\" class=\"frm_primary_label\">Please indicate which option best describes your activity levels:\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_zeci43_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_2757-2754-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2757]=Gets no exercise].png\'><div class=\"frm_label\">		 Gets no exercise</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_2757-2754-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2757]=Gets little exercise].png\'><div class=\"frm_label\">		 Gets little exercise</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_2757-2754-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2757]=Exercises regularly].png\'><div class=\"frm_label\">		 Exercises regularly</div></div>\n</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_2763_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Blood pressure</h3>\r\n\r\n\r\n<div id=\"frm_field_2766_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>Please provide a blood pressure reading if you have access to a machine.</p>\n<p>For a list of validated home blood pressure monitors, visit <a href=\"https://bihsoc.org/bp-monitors/\" rel=\"noreferrer noopener\" target=\"_blank\">www.bihsoc.org/bp-monitors</a> or discuss with your pharmacy.</p>\n</div>\n<div id=\"frm_field_2769_container\" class=\"frm_form_field form-field  frm_top_container sp_tooltip\">\r\n    <div class=\"frm_label frm_primary_label\">Date of reading:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2769]</div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_2q5vf\">Please use date format: DD/MM/YYYY</div>\r\n    \r\n</div>\n<div id=\"frm_field_2775_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Systolic \"Higher\":\r\n        \r\n    </div>\r\n    <div class=\'input number\'>[2775]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2781_container\" class=\"frm_form_field form-field  frm_top_container frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Diastolic \"Lower\":\r\n        \r\n    </div>\r\n    <div class=\'input number\'>[2781]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2784_container\" class=\"frm_form_field form-field  frm_top_container frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Heart Rate:\r\n        \r\n    </div>\r\n    <div class=\'input number\'>[2784]</div>\r\n    \r\n    \r\n</div>\n</div>\n    </div>\r\n    \r\n  </div>\r\n<div class=\"hide\">[frm-conditions]{\"2703\":{\"field_id\":[2697],\"hide_opt\":[\"Smoker\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2709\":{\"field_id\":[2706],\"hide_opt\":[\"Cigarettes\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2712\":{\"field_id\":[2706],\"hide_opt\":[\"Cigars\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2715\":{\"field_id\":[2706],\"hide_opt\":[\"Rollups\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2718\":{\"field_id\":[2706],\"hide_opt\":[\"Pipe\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2724\":{\"field_id\":[\"2721\"],\"hide_opt\":[\"Yes\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2730\":{\"field_id\":[\"2697\"],\"hide_opt\":[\"Ex smoker\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2736\":{\"field_id\":[2733],\"hide_opt\":[\"Cigarettes\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2739\":{\"field_id\":[2733],\"hide_opt\":[\"Cigars\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2742\":{\"field_id\":[2733],\"hide_opt\":[\"Rollups\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"2745\":{\"field_id\":[2733],\"hide_opt\":[\"Pipe\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"}}[/frm-conditions]</div>'),
(5,111,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_111_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_4293_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Section</h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_4302_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\"></h3>\r\n\r\n\r\n<div id=\"frm_field_4305_container\" class=\"frm_form_field form-field  frm_top_container frm_two_col\">\r\n    <div  id=\"field_1n2du_label\" class=\"frm_primary_label\">I would like to decline (Please select all that apply):\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_1n2du_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Cancer Care Review].png\'><div class=\"frm_label\"> Cancer Care Review</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-1\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Atrial Fibrillation].png\'><div class=\"frm_label\"> Atrial Fibrillation</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-2\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Alcohol Consumption Review].png\'><div class=\"frm_label\"> Alcohol Consumption Review</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-3\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Asthma Review].png\'><div class=\"frm_label\"> Asthma Review</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-4\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Blood Pressure Review].png\'><div class=\"frm_label\"> Blood Pressure Review</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-5\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=BMI].png\'><div class=\"frm_label\"> BMI</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-6\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Coronary Heart Disease Review].png\'><div class=\"frm_label\"> Coronary Heart Disease Review</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-7\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=COPD].png\'><div class=\"frm_label\"> COPD</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-8\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Depression].png\'><div class=\"frm_label\"> Depression</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-9\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Diabetes].png\'><div class=\"frm_label\"> Diabetes</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-10\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Heart Failure].png\'><div class=\"frm_label\"> Heart Failure</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-11\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Hypertension].png\'><div class=\"frm_label\"> Hypertension</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-12\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Mental Health].png\'><div class=\"frm_label\"> Mental Health</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-13\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Non-Diabetic Hyperglycaemia].png\'><div class=\"frm_label\"> Non-Diabetic Hyperglycaemia</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-14\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Rheumatoid Arthritis].png\'><div class=\"frm_label\"> Rheumatoid Arthritis</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-15\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Smoking].png\'><div class=\"frm_label\"> Smoking</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-16\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Stroke/TIA].png\'><div class=\"frm_label\"> Stroke/TIA</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-17\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Vaccination].png\'><div class=\"frm_label\"> Vaccination</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-18\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Medication Review].png\'><div class=\"frm_label\"> Medication Review</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_4305-4302-19\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4305]=Cervical Screening Programme].png\'><div class=\"frm_label\"> Cervical Screening Programme</div></div>\n</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_4311_container\" class=\"frm_form_field  frm_html_container form-field\">\n<div class=\"clearboth\"><!--comment--></div>\n</div>\n<div id=\"frm_field_4314_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Cancer Care</h3>\r\n\r\n\r\n<div id=\"frm_field_4317_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me any further invitations to have a Cancer Care review. I assume full responsibility for this decision, and I understand that I can contact the practice to reinstate it or speak to a clinician at any time.</p>\n</div>\n</div>\n<div id=\"frm_field_4323_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Atrial Fibrillation</h3>\r\n\r\n\r\n<div id=\"frm_field_4326_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me any further invitations to have an Atrial Fibrillation review or to offer medication. I assume full responsibility for this decision, and I understand that I can contact the practice to reinstate it or speak to a clinician at any time.</p>\n</div>\n</div>\n<div id=\"frm_field_4332_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Asthma</h3>\r\n\r\n\r\n<div id=\"frm_field_4335_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me any further invitations to have an Asthma review. I assume full responsibility for this decision, and I understand that I can contact the practice to reinstate it or speak to a clinician at any time.</p>\n</div>\n</div>\n<div id=\"frm_field_4341_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Alcohol Consumption</h3>\r\n\r\n\r\n<div id=\"frm_field_4344_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me any further invitations to have an Alcohol Consumption review. I assume full responsibility for this decision, and I understand that I can contact the practice to reinstate it or speak to a clinician at any time.</p>\n</div>\n</div>\n<div id=\"frm_field_4350_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">BMI</h3>\r\n\r\n\r\n<div id=\"frm_field_4353_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me any further invitations to record my BMI. I assume full responsibility for this decision, and I understand that I can contact the practice to reinstate it or speak to a clinician at any time.</p>\n</div>\n</div>\n<div id=\"frm_field_4359_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Blood Pressure</h3>\r\n\r\n\r\n<div id=\"frm_field_4362_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me any further invitations to have a Blood Pressure review. I assume full responsibility for this decision, and I understand that I can contact the practice to reinstate it or speak to a clinician at any time.</p>\n</div>\n</div>\n<div id=\"frm_field_4368_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Coronary Heart Disease</h3>\r\n\r\n\r\n<div id=\"frm_field_4371_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me any further invitations to have a Coronary Heart Disease review. I assume full responsibility for this decision, and I understand that I can contact the practice to reinstate it or speak to a clinician at any time.</p>\n</div>\n</div>\n<div id=\"frm_field_4377_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">COPD</h3>\r\n\r\n\r\n<div id=\"frm_field_4380_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me any further invitations to have a COPD review this year. I assume full responsibility for this decision, and I understand that I can contact the practice to reinstate it or speak to a clinician at any time.</p>\n</div>\n</div>\n<div id=\"frm_field_4386_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Depression</h3>\r\n\r\n\r\n<div id=\"frm_field_4389_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Please do not send me an