(6,114,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_114_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_4527_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Section</h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_4536_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container horizontal_radio\">\r\n    <div  id=\"field_3zc5u_label\" class=\"frm_primary_label\">Have you been offered a follow up appointment by the practice?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_3zc5u_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_4536-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[4536]=Yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_4536-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[4536]=No].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_4539_container\" class=\"frm_form_field form-field  frm_required_field frm_inline_container horizontal_radio\">\r\n    <div  id=\"field_veb6_label\" class=\"frm_primary_label\">Terms and conditions\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_veb6_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_4539-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[4539]=confirmtermsandconditions].png\'><div class=\"frm_label\"> I confirm that I have had my first appointment with my GP. I confirm that this is not an emergency and understand the surgery cannot help while it is closed. If I need help right now, I will use the NHS 111 service. In an emergency, I will call 999 or go to A&amp;E.</div></div>\n</div>\r\n    \r\n    \r\n</div>\n    </div>\r\n    \r\n  <