(7,73,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_73_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_2110_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\"></h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_2116_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">About the problem</h3>\r\n\r\n\r\n<div id=\"frm_field_2119_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container preview_answer\">\r\n    <div class=\"frm_label frm_primary_label\">Tell us about the problem\r\n        \r\n    </div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_xzd2s\">It may help to describe the problem as if you were speaking to someone</div>\r\n    <div class=\'textarea\' style=\'min-height:94px\'>[2119]</div>\r\n    \r\n</div>\n<div id=\"frm_field_2122_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">How long has this been a problem?\r\n        \r\n    </div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_ku3zc\">It\'s helpful to tell us whether it\'s been days, weeks, months or years</div>\r\n    <div class=\'input text\'>[2122]</div>\r\n    \r\n</div>\n<div id=\"frm_field_2125_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Do you have an idea about what is causing the problem?\r\n        \r\n    </div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_9d20r\">This might be something that happened or that you discovered around the time your symptoms began</div>\r\n    <div class=\'textarea\' style=\'min-height:43px\'>[2125]</div>\r\n    \r\n</div>\n<div id=\"frm_field_2128_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Can you think of anything that is worrying you about the problem?\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:43px\'>[2128]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2182_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Is there a member of staff who would be best to deal with this problem?\r\n        \r\n    </div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_j0ch5\">We cannot guarantee this as it depends on their availability</div>\r\n    <div class=\'input text\'>[2182]</div>\r\n    \r\n</div>\n</div>\n<div id=\"frm_field_2433_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div  id=\"field_f87al_label\" class=\"frm_primary_label\">Upload a photograph or document\r\n        \r\n    </div>\r\n    \n\n<div class=\"frm_dropzone frm_single_upload frm_clearfix\" id=\"file2433_dropzone\" role=\"group\" >\n	<div class=\"fallback\">\n		<div class=\'input\'></div>\n				<div class=\"frm_clearfix \"></div>\n	</div>\n	<div class=\"dz-message needsclick\">\n		<span class=\"frm_icon_font frm_upload_icon\"></span>\n		<span class=\"frm_upload_text\"><button type=\"button\">Drop a file here or click to upload</button></span>\n		<span class=\"frm_compact_text\"><button type=\"button\">Choose File</button></span>\n		<div class=\"frm_small_text\">\n			Maximum upload size: 20.97MB		</div>\n	</div>\n</div>\n\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2134_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container vertical_radio\">\r\n    <div  id=\"field_3hrkb_label\" class=\"frm_primary_label\">How would you prefer to be contacted?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_3hrkb_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_2134-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2134]=Email].png\'><div class=\"frm_label\">		 Email</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_2134-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2134]=Phone].png\'><div class=\"frm_label\">		 Phone</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_2134-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2134]=Text message].png\'><div class=\"frm_label\">		 Text message</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_2134-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[2134]=Video call].png\'><div class=\"frm_label\">		 Video call</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6818_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Are there any times when you cannot be contacted?\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:43px\'>[6818]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2194_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container vertical_radio\">\r\n    <div  id=\"field_gi3kn_label\" class=\"frm_primary_label\">Terms and conditions\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_gi3kn_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_2194-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[2194]=confirmtermsandconditions].png\'><div class=\"frm_label\"> I confirm that this is not an emergency and understand the surgery cannot help while it is closed. If I need help right now, I will use the NHS 111 service. In an emergency, I will call 999 or go to A&amp;E.</div></div>\n</div>\r\n    \r\n    \r\n</div>\n    </div>\r\n    \r\n  </div>\r\n<div class=\"hide\">[frm-conditions]null[/frm-conditions]</div>'),
(8,120,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_120_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_5040_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification frm_hide_section\">\r\n<h3 class=\"frm_pos_none frm_section_spacing\"></h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_6861_container\" class=\"frm_form_field frm_section_heading form-field \">\n<h3 class=\"frm_pos_top frm_section_spacing\">About you</h3>\n\n\n<div id=\"frm_field_5049_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Height (in Meters):\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[5049]</div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_pe233\">eg. 1.75</div>\r\n    \r\n</div>\n<div id=\"frm_field_5052_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Weight (in Kilograms):\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[5052]</div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_jsm8t\">eg. 60.6</div>\r\n    \r\n</div>\n<div id=\"frm_field_5055_container\" class=\"frm_form_field form-field  frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">BMI:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[5055]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_5058_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Medication</h3>\r\n\r\n\r\n<div id=\"frm_field_5061_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container horizontal_radio\">\r\n    <div  id=\"field_bvdmw_label\" class=\"frm_primary_label\">Are you having any problems with your medication?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_bvdmw_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_5061-5058-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5061]=Yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5061-5058-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5061]=No].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5064_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Please briefly explain what problems you are having:\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:43px\'>[5064]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_5070_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Smoking</h3>\r\n\r\n\r\n<div id=\"frm_field_5073_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container horizontal_radio\">\r\n    <div  id=\"field_vhi68f32_label\" class=\"frm_primary_label\">Smoking status:\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_vhi68f32_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_5073-5070-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5073]=smoker].png\'><div class=\"frm_label\">		 Smoker</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5073-5070-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5073]=neversmoked].png\'><div class=\"frm_label\">		 Never smoked</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5073-5070-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5073]=exsmoker].png\'><div class=\"frm_label\">		 Ex-smoker</div></div>\n</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_5079_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Smoker</h3>\r\n\r\n\r\n<div id=\"frm_field_5082_container\" class=\"frm_form_field form-field  frm_top_container horizontal_radio\">\r\n    <div  id=\"field_hlute_label\" class=\"frm_primary_label\">What do you mainly smoke?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_hlute_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_5082-5079-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5082]=Cigarettes].png\'><div class=\"frm_label\"> Cigarettes</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_5082-5079-1\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5082]=Cigars].png\'><div class=\"frm_label\"> Cigars</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_5082-5079-2\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5082]=Rollups].png\'><div class=\"frm_label\"> Rollups</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_5082-5079-3\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5082]=Pipe].png\'><div class=\"frm_label\"> Pipe</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_5082-5079-4\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5082]=E Cigarettes].png\'><div class=\"frm_label\"> E Cigarettes</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5085_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container horizontal_radio\">\r\n    <div  id=\"field_x24yy_label\" class=\"frm_primary_label\">How many cigarettes do you smoke in a day?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_x24yy_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_5085-5079-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/r