lass=\"frm_opt_container\" aria-labelledby=\"field_xbppc_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_5109-5106-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5109]=Cigarettes].png\'><div class=\"frm_label\"> Cigarettes</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_5109-5106-1\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5109]=Cigars].png\'><div class=\"frm_label\"> Cigars</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_5109-5106-2\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5109]=Rollups].png\'><div class=\"frm_label\"> Rollups</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_5109-5106-3\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5109]=Pipe].png\'><div class=\"frm_label\"> Pipe</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_5109-5106-4\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[5109]=E Cigarettes].png\'><div class=\"frm_label\"> E Cigarettes</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5112_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container horizontal_radio\">\r\n    <div  id=\"field_ds6th_label\" class=\"frm_primary_label\">How many cigarettes did you smoke in a day?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_ds6th_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_5112-5106-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5112]=1 to 9].png\'><div class=\"frm_label\">		 1 to 9</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5112-5106-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5112]=10 to 19].png\'><div class=\"frm_label\">		 10 to 19</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5112-5106-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5112]=20 to 39].png\'><div class=\"frm_label\">		 20 to 39</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5112-5106-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5112]=40 or more].png\'><div class=\"frm_label\">		 40 or more</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5115_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container horizontal_radio\">\r\n    <div  id=\"field_j110n_label\" class=\"frm_primary_label\">How many cigars did you smoke in a day?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_j110n_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_5115-5106-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5115]=1 to 9].png\'><div class=\"frm_label\">		 1 to 9</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5115-5106-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5115]=10 to 19].png\'><div class=\"frm_label\">		 10 to 19</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5115-5106-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5115]=20 to 39].png\'><div class=\"frm_label\">		 20 to 39</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_5115-5106-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[5115]=40 or more].png\'><div class=\"frm_label\">		 40 or more</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5118_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Rollups - How many grams of tobacco did you smoke per week?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[5118]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5121_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Pipe - How many grams of tobacco did you smoke per week?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[5121]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5124_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">When did you give up smoking?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[5124]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_5130_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Blood pressure diary</h3>\r\n\r\n\r\n<div id=\"frm_field_5136_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>For a list of validated home blood pressure monitors, visit <a href=\"https://bihsoc.org/bp-monitors/\" target=\"_blank\" rel=\"noopener\">www.bihsoc.org/bp-monitors</a> or discuss with your pharmacy.</p>\n</div>\n<div id=\"frm_field_5139_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<h4>Patient instructions</h4>\n<ul>\n<li>In the morning, ensure that you are rested and have taken no exercise in the last 30 minutes.</li>\n<li>Then sit in a chair comfortably upright with your arm supported on a table beside you, with both feet on the ground.</li>\n<li>Put the cuff on your upper arm (5cm above your elbow) resting on the table, the cuff should be roughly at the level of your heart.</li>\n<li>Press the on/start button on the BP monitor and take two readings at least 1 minute apart.</li>\n<li>Record the readings below with your pulse rate and any comments.</li>\n<li>Repeat that evening and for a total of 7 days using alternate arms.</li>\n</ul>\n</div>\n</div>\n<div id=\"frm_field_5145_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Day 1</h3>\r\n\r\n\r\n<div id=\"frm_field_5148_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Date:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[5148]</div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_nmk3gt\">Please use this date format: DD/MM/YYYY</div>\r\n    \r\n</div>\n<div id=\"frm_field_5151_container\" class=\"frm_form_field  frm_html_container form-field\"><strong>Morning Measurements</strong></div>\n<div id=\"frm_field_5154_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Systolic \"Higher\"\r\n        \r\n    </div>\r\n    <div class=\'input number\'>[5154]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5160_container\" class=\"frm_form_field form-field  frm_top_container frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Diastolic \"Lower\"\r\n        \r\n    </div>\r\n    <div class=\'input number\'>[5160]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5163_container\" class=\"frm_form_field form-field  frm_top_container frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Heart Rate\r\n        \r\n    </div>\r\n    <div class=\'input number\'>[5163]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5166_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Systolic \"Higher\"\r\n        \r\n    </div>\r\n    <div class=\'input number\'>[5166]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5172_container\" class=\"frm_form_field form-field  frm_top_container frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Diastolic \"Lower\"\r\n        \r\n    </div>\r\n    <div class=\'input number\'>[5172]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_5175_container\" class=\"frm_form_field form-field  frm_top_container frm_inline\">\r\n    <div class=\"frm_label frm_primary_label\">Heart Rate\r\n        \r\n    </div>\r\n    <div class=