al_radio\">\r\n    <div  id=\"field_6bb4rg_label\" class=\"frm_primary_label\">Do you give us permission to discuss your medical records with them?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_6bb4rg_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_879-873-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[879]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_879-873-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[879]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_176_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Previous details</h3>\r\n\r\n\r\n<div id=\"frm_field_177_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Previous address in UK:\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:60px\'>[177]</div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_gms1_previousaddress3\">Please include postcode.</div>\r\n    \r\n</div>\n<div id=\"frm_field_884_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Name and address of previous GP practice:\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:60px\'>[884]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_181_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">If you are from abroad and registering with the NHS for the first time</h3>\r\n\r\n\r\n<div id=\"frm_field_885_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Date you came to live in the UK:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[885]</div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_3pxkwq\">Please use this date format: DD/MM/YYYY</div>\r\n    \r\n</div>\n</div>\n<div id=\"frm_field_886_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">If you are returning from abroad and have previously been registered with the NHS</h3>\r\n\r\n\r\n<div id=\"frm_field_888_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Date you left the UK:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[888]</div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_2lnnxi\">Please use this date format: DD/MM/YYYY</div>\r\n    \r\n</div>\n<div id=\"frm_field_889_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Date you returned to the UK:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[889]</div>\r\n    <div class=\"frm_description\" id=\"frm_desc_field_4savyz\">Please use this date format: DD/MM/YYYY</div>\r\n    \r\n</div>\n</div>\n<div id=\"frm_field_2367_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Were you ever registered with an Armed Forces GP</h3>\r\n\r\n\r\n<div id=\"frm_field_2373_container\" class=\"frm_form_field form-field  frm_top_container horizontal_radio\">\r\n    <div  id=\"field_m1bpl_label\" class=\"frm_primary_label\">Please indicate if you have served in the UK Armed Forces and/or been registered with a Ministry of Defence GP in the UK or overseas:\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_m1bpl_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_2373-2367-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[2373]=Regular].png\'><div class=\"frm_label\"> Regular</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_2373-2367-1\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[2373]=Reservist].png\'><div class=\"frm_label\"> Reservist</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_2373-2367-2\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[2373]=Veteran].png\'><div class=\"frm_label\"> Veteran</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_2373-2367-3\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[2373]=Family Member (Spouse, Civil Partner, Service Child)].png\'><div class=\"frm_label\"> Family Member (Spouse, Civil Partner, Service Child)</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2376_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Address before enlisting (including postcode):\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:77px\'>[2376]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2385_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Service or Personnel number:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2385]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2382_container\" class=\"frm_form_field form-field  frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Enlistment date:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2382]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2379_container\" class=\"frm_form_field form-field  frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Discharge date (if applicable):\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2379]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_215_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Ethnicity</h3>\r\n\r\n\r\n<div id=\"frm_field_6351_container\" class=\"frm_form_field form-field  frm_top_container vertical_radio\">\r\n    <div  id=\"field_elnf4_label\" class=\"frm_primary_label\">What is your ethnic group?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_elnf4_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_6351-215-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=White: British].png\'><div class=\"frm_label\">		 White: British</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=White: Irish].png\'><div class=\"frm_label\">		 White: Irish</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=White: Irish Traveller].png\'><div class=\"frm_label\">		 White: Irish Traveller</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=White: Traveller].png\'><div class=\"frm_label\">		 White: Traveller</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-4\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=White: Gypsy/Romany].png\'><div class=\"frm_label\">		 White: Gypsy/Romany</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-5\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=White: Polish].png\'><div class=\"frm_label\">		 White: Polish</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-6\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=White: Any other White background].png\'><div class=\"frm_label\">		 White: Any other White background</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-7\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Mixed: White and Black Caribbean].png\'><div class=\"frm_label\">		 Mixed: White and Black Caribbean</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-8\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Mixed: White and Black African].png\'><div class=\"frm_label\">		 Mixed: White and Black African</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-9\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Mixed: White and Asian].png\'><div class=\"frm_label\">		 Mixed: White and Asian</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-10\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Mixed: Any other Mixed background].png\'><div class=\"frm_label\">		 Mixed: Any other Mixed background</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-11\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Asian or Asian British: Indian].png\'><div class=\"frm_label\">		 Asian or Asian British: Indian</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-12\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Asian or Asian British: Pakistani].png\'><div class=\"frm_label\">		 Asian or Asian British: Pakistani</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-13\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Asian or Asian British: Bangladeshi].png\'><div class=\"frm_label\">		 Asian or Asian British: Bangladeshi</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-14\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Asian or Asian British: Any other Asian background].png\'><div class=\"frm_label\">		 Asian or Asian British: Any other Asian background</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-15\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Black or Black British: Caribbean].png\'><div class=\"frm_label\">		 Black or Black British: Caribbean</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-16\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Black or Black British: African].png\'><div class=\"frm_label\">		 Black or Black British: African</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-17\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Black or Black British: Somali].png\'><div class=\"frm_label\">		 Black or Black British: Somali</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-18\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Black or Black British: Nigerian].png\'><div class=\"frm_label\">		 Black or Black British: Nigerian</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-19\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Black or Black British: Any other Black background].png\'><div class=\"frm_label\">		 Black or Black British: Any other Black background</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-20\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Other ethnic group: Chinese].png\'><div class=\"frm_label\">		 Other ethnic group: Chinese</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-21\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Other ethnic group: Filipino].png\'><div class=\"frm_label\">		 Other ethnic group: Filipino</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-22\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Other ethnic group: Any other ethnic group].png\'><div class=\"frm_label\">		 Other ethnic group: Any other ethnic group</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6351-215-23\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6351]=Prefer not to say].png\'><div class=\"frm_label\">		 Prefer not to say</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_217_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Please specify your ethnic group or background:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[217]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_1223_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Supplementary questions</h3>\r\n\r\n\r\n<div id=\"frm_field_2364_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>Anybody in England can register with a GP practice and receive free medical care from that practice.</p>\n<p>However, if you are not \'ordinarily resident\' in the UK you may have to pay for NHS treatment outside of the GP practice. Being ordinarily resident broadly means living lawfully in the UK on a properly settled basis for the time being. In most cases, nationals of countries outside the European Economic Area must also have the status of \'indefinite leave to remain\' in the UK.</p>\n<p>Some services, such as diagnostic tests of suspected infectious diseases and any treatment of those diseases are free of charge to all people, while some groups who are not ordinarily resident here are exempt from all treatment charges.</p>\n<p>More information on ordinary residence, exemptions and paying for NHS services can be found in the Visitor and Migrant patient leaflet, available from your GP practice. You can also find more information about <a href=\"https://www.nhs.uk/nhs-services/visiting-or-moving-to-england/\" target=\"_blank\" rel=\"noopener\">visiting or moving to England</a> on the NHS website.</p>\n</div>\n<div id=\"frm_field_6854_container\" class=\"frm_form_field form-field  frm_top_container vertical_radio\">\n    <div  id=\"field_59obq_label\" class=\"frm_primary_label\">Are you ordinarily resident in the UK?\n        <span class=\"frm_required\" aria-hidden=\"true\"></span>\n    </div>\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_59obq_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_6854-1223-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6854]=Yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_6854-1223-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[6854]=No].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\n    \n    \n</div>\n</div>\n<div id=\"frm_field_1226_container\" class=\"frm_form_field frm_section_heading form-field  frm_hide_section\">\r\n<h3 class=\"frm_pos_none frm_section_spacing\">Not ordinarily resident</h3>\r\n\r\n\r\n<div id=\"frm_field_1228_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>You may be asked to provide proof of entitlement in order to receive free NHS treatment outside of the GP practice, otherwise you may be charged for your treatment. A valid exemption includes for example, an EHIC, or payment of the Immigration Health Charge (\"the Surcharge\"), when accompanied by a valid visa. Even if you have to pay for a service, you will always be provided with any immediately necessary or urgent treatment, regardless of advance payment.</p>\n<p>The information you give on this form will be used to assist in identifying your chargeable status, and may be shared, including with NHS secondary care organisations (e.g. hospitals) and NHS Digital, for the purposes of validation, invoicing and cost recovery. You may be contacted on behalf of the NHS to confirm any details you have provided.</p>\n<p>You are declaring that the information given on this form is correct and complete. If it is not correct, appropriate action may be taken against you.</p>\n<p>A parent/guardian should complete this section on behalf of a child under 16.</p>\n</div>\n<div id=\"frm_field_1229_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container vertical_radio\">\r\n    <div  id=\"field_faj4m_label\" class=\"frm_primary_label\">Do you understand your chargeable status?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_faj4m_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_1229-1226-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1229]=I understand that I may need to pay for NHS treatment outside of the GP practice].png\'><div class=\"frm_label\">		 I understand that I may need to pay for NHS treatment outside of the GP practice</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1229-1226-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1229]=I understand I have a valid exemption from paying for NHS treatment outside of the GP practice and IÂ can provide documents to support this when requested].png\'><div class=\"frm_label\">		 I understand I have a valid exemption from paying for NHS treatment outside of the GP practice and IÂ can provide documents to support this when requested</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1229-1226-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1229]=I don&#039;t know my chargeable status].png\'><div class=\"frm_label\">		 I don\'t know my chargeable status</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1231_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Signature:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1231]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1232_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Print Name:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1232]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1233_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">On behalf of:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1233]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1234_container\" class=\"frm_form_field form-field  frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Relationship to patient:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1234]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1235_container\" class=\"frm_form_field form-field  frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Date:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1235]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_1236_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">European Economic Area (EEA) country</h3>\r\n\r\n\r\n<div id=\"frm_field_6857_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p><a href=\"https://www.gov.uk/eu-eea\" target=\"blank\">List of EEA countries</a></p>\n</div>\n<div id=\"frm_field_1238_container\" class=\"frm_form_field form-field  frm_top_container horizontal_radio\">\r\n    <div  id=\"field_fzfsb_label\" class=\"frm_primary_label\">Do you live in another EEA country, or have moved to the UK to study or retire, or live in the UK but work in another EEA member state?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_fzfsb_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_1238-1236-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1238]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1238-1236-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1238]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1239_container\" class=\"frm_form_field form-field  frm_top_container horizontal_radio\">\r\n    <div  id=\"field_nm4oq_label\" class=\"frm_primary_label\">Do you have a non-UK European Health Insurance Card (EHIC) or a Provisional Replacement Certificate (PRC) ?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_nm4oq_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_1239-1236-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1239]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1239-1236-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1239]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1240_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>If you are visiting from another EEA country and do not hold a current EHIC (or Provisional Replacement Certificate (PRC))/S1, you may be billed for the cost of any treatment received outside of the GP practice, including at a hospital.</p>\n</div>\n</div>\n<div id=\"frm_field_1242_container\" class=\"frm_form_field frm_section_heading form-field  frm_hide_section\">\r\n<h3 class=\"frm_pos_none frm_section_spacing\">EHIC/PRC</h3>\r\n\r\n\r\n<div id=\"frm_field_1244_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>Please enter the details from your EHIC or PRC below.</p>\n</div>\n<div id=\"frm_field_1245_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Country Code:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1245]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1246_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">3. Name:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1246]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1247_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">4. Given Names:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1247]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1248_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">5. Date of Birth:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1248]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1249_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">6. Personal Identification Number:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1249]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1250_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">7. Identification number of the institution:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1250]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1251_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">8. Identification number of the card:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1251]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1252_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">9. Expiry Date:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1252]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1253_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">PRC validity period - from:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1253]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1254_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">PRC validity period - to:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[1254]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_1255_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">S1 form</h3>\r\n\r\n\r\n<div id=\"frm_field_1257_container\" class=\"frm_form_field form-field  frm_top_container vertical_radio\">\r\n    <div  id=\"field_wr2fg_label\" class=\"frm_primary_label\">Do you have an S1 Form?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_wr2fg_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_1257-1255-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[1257]=haves1].png\'><div class=\"frm_label\"> I have an S1 form (e.g. you are retiring to the UK or you have been posted here by your employer for work or you live in the UK but work in another EEA member state).</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1258_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p><strong>Please give your S1 form to the practice staff.</strong></p>\n</div>\n</div>\n<div id=\"frm_field_1259_container\" class=\"frm_form_field frm_section_heading form-field  hide-item\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">How will your EHIC/PRC/S1 data be used?</h3>\r\n\r\n\r\n<div id=\"frm_field_1261_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>By using your EHIC or PRC for NHS treatment costs your EHIC or PRC data and GP appointment data will be shared with NHS secondary care (hospitals) and NHS Digital solely for the purposes of cost recovery. Your clinical data will not be shared in the cost recovery process.</p>\n<p>Your EHIC, PRC or S1 information will be shared with The Department for Work and Pensions for the purpose of recovering your NHS costs from your home country.</p>\n</p></div>\n</div>\n<div id=\"frm_field_6858_container\" class=\"frm_form_field frm_section_heading form-field \">\n<h3 class=\"frm_pos_top frm_section_spacing\">Language</h3>\n\n\n<div id=\"frm_field_870_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half horizontal_radio\">\r\n    <div  id=\"field_y9g8u4_label\" class=\"frm_primary_label\">Do you speak English?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_y9g8u4_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_870-6858-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[870]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_870-6858-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[870]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_871_container\" class=\"frm_form_field form-field  frm_top_container frm_half horizontal_radio\">\r\n    <div  id=\"field_e824oo_label\" class=\"frm_primary_label\">Do you read English?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_e824oo_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_871-6858-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[871]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_871-6858-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[871]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_872_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Main Spoken Language:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[872]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6741_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Main Reading Language:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[6741]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_241_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Carers</h3>\r\n\r\n\r\n<div id=\"frm_field_242_container\" class=\"frm_form_field form-field  frm_inline_container horizontal_radio\">\r\n    <div  id=\"field_fsselm_label\" class=\"frm_primary_label\">Do you have a carer?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_fsselm_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_242-241-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[242]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_242-241-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[242]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_892_container\" class=\"frm_form_field form-field  frm_inline_container horizontal_radio\">\r\n    <div  id=\"field_7j2uul_label\" class=\"frm_primary_label\">Are you a carer for someone?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_7j2uul_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_892-241-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[892]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_892-241-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[892]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_893_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Name of carer:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[893]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_894_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Phone Number:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[894]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_895_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Address:\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:60px\'>[895]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_896_container\" class=\"frm_form_field form-field  frm_top_container horizontal_radio\">\r\n    <div  id=\"field_ut742c_label\" class=\"frm_primary_label\">Do you give us permission to discuss your medical record with your carer?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_ut742c_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_896-241-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[896]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_896-241-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[896]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_237_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Lifestyle</h3>\r\n\r\n\r\n<div id=\"frm_field_238_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Height:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[238]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_239_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Weight:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[239]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_897_container\" class=\"frm_form_field form-field  frm_top_container vertical_radio\">\r\n    <div  id=\"field_oiewxp_label\" class=\"frm_primary_label\">Smoking Status:\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_oiewxp_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_897-237-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[897]=currentsmoker].png\'><div class=\"frm_label\">		 Current Smoker</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_897-237-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[897]=exsmoker].png\'><div class=\"frm_label\">		 Ex Smoker</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_897-237-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[897]=neversmoked].png\'><div class=\"frm_label\">		 Never Smoked</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2391_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">How many do you smoke per day?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2391]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_898_container\" class=\"frm_form_field form-field  frm_top_container frm_half horizontal_radio\">\r\n    <div  id=\"field_hed31m_label\" class=\"frm_primary_label\">Are you interested in advice on how to quit?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_hed31m_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_898-237-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[898]=yes].png\'><div class=\"frm_label\">		 Yes</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_898-237-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[898]=no].png\'><div class=\"frm_label\">		 No</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_899_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">How many did you smoke per day?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[899]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_900_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">When did you stop?\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[900]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_901_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Please state how much exercise and what type of exercise you do per week:\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:60px\'>[901]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_246_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Alcohol consumption</h3>\r\n\r\n\r\n<div id=\"frm_field_247_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<h4>This is one unit of alcohol:</h4>\n<div style=\"margin:15px 0px 15px 0px; text-align:center;\"><img style= \"width:100%; height:auto;\" src=\'/wp-content/uploads/2019/06/alcohol-units-new-IW.jpg\' alt=\"Amount of different types of drink representing one unit of alcohol\" class=\"alcohol1\"></div>\n<h4>And each one of these, is more than one unit:</h4>\n<div style=\"margin:15px 0px 15px 0px; text-align:center;\"><img style= \"width:100%; height:auto;\" src=\'/wp-content/uploads/2019/06/alcohol-units-new-IW-2.jpg\' alt=\"Amount of different types of drink representing more than one unit of alcohol\" class=\"alcohol2\"></div>\n</div>\n<div id=\"frm_field_248_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_half vertical_radio\">\r\n    <div  id=\"field_nkhxlk_label\" class=\"frm_primary_label\">How often do you have a drink containing alcohol?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_nkhxlk_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_248-246-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[248]=Never - 0].png\'><div class=\"frm_label\">		 Never</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_248-246-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[248]=Monthly or less - 1].png\'><div class=\"frm_label\">		 Monthly or less</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_248-246-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[248]=2-4 times per month - 2].png\'><div class=\"frm_label\">		 2-4 times per month</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_248-246-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[248]=2-3 times per week - 3].png\'><div class=\"frm_label\">		 2-3 times per week</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_248-246-4\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[248]=4+ times per week - 4].png\'><div class=\"frm_label\">		 4+ times per week</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_249_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_half vertical_radio\">\r\n    <div  id=\"field_96uk