ass=\"frm_radio\" id=\"frm_radio_921-915-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[921]=poor].png\'><div class=\"frm_label\">		 Poor</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_921-915-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[921]=blind].png\'><div class=\"frm_label\">		 Registered Blind</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_922_container\" class=\"frm_form_field form-field  frm_top_container vertical_radio\">\r\n    <div  id=\"field_ty40y_label\" class=\"frm_primary_label\">How is your hearing?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_ty40y_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_922-915-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[922]=good].png\'><div class=\"frm_label\">		 Good</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_922-915-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[922]=poor].png\'><div class=\"frm_label\">		 Poor</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_922-915-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[922]=partdeaf].png\'><div class=\"frm_label\">		 Partially Deaf</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_922-915-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[922]=deaf].png\'><div class=\"frm_label\">		 Deaf</div></div>\n</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_2394_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Family history</h3>\r\n\r\n\r\n<div id=\"frm_field_919_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Please list any family history of illnesses (including the relative and year they were diagnosed):\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:60px\'>[919]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_2400_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Nominate a pharmacy</h3>\r\n\r\n\r\n<div id=\"frm_field_2406_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p><a href=\"https://www.nhs.uk/service-search/pharmacy/find-a-pharmacy\" target=\"_blank\">Find a local pharmacy</a></p>\n</div>\n<div id=\"frm_field_2409_container\" class=\"frm_form_field form-field  frm_top_container frm_first frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Pharmacy Name:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2409]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2412_container\" class=\"frm_form_field form-field  frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Pharmacy Address:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2412]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2415_container\" class=\"frm_form_field form-field  frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Pharmacy Postcode:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[2415]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_197_container\" class=\"frm_form_field frm_section_heading form-field  hide-item\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">NHS Organ Donor registration</h3>\r\n\r\n\r\n<div id=\"frm_field_930_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>For more information on organ donation, please visit: <a href=\"https://www.organdonation.nhs.uk/\" target=\"_blank\">www.organdonation.nhs.uk</a></p>\n</div>\n</div>\n<div id=\"frm_field_200_container\" class=\"frm_form_field frm_section_heading form-field  hide-item\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">NHS Blood Donor registration</h3>\r\n\r\n\r\n<div id=\"frm_field_931_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p>If you would like to join the NHS Blood Donor Register as someone who may be contacted and would be prepared to donate blood, please visit their website on: <a href=\"https://www.blood.co.uk\" target=\"_blank\">www.blood.co.uk</a> or call direct on 03001232323</p>\n</div>\n</div>\n<div id=\"frm_field_264_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">What happens to my information?</h3>\r\n\r\n\r\n<div id=\"frm_field_265_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Personal and medical information about patients registered at this practice are primarily kept electronically, although some is kept in paper form. Some information will be sent to hospital consultants and other health professionals to whom you are referred by your GP in order to provide continued healthcare and obtain treatment for you.</p>\n<p>We sometimes use accredited suppliers for our communication with you, for example when we send recall letters for review clinics or medication reviews. All suppliers we use are checked carefully to ensure they comply with strict confidentiality protocols.</p>\n<p>To ensure the security of all patient information, all staff that has access to your records is covered by confidentiality clauses in their contracts and the Data Protection Act and the Freedom of Information Act. Our guiding principle is that we hold your records in strict confidence.</p>\n</div>\n<div id=\"frm_field_1315_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p><strong>I certify that the information I have provided is correct and consent to my personal and medical information being used as stated above.</strong></p>\n</div>\n<div id=\"frm_field_926_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Signature:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[926]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_203_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Date:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[203]</div>\r\n    \r\n    \r\n</div>\n</div>\n<div id=\"frm_field_2418_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div  id=\"field_owden_label\" class=\"frm_primary_label\">To help complete your registration, please upload proof of identity, this should include photographic ID and proof of address.\r\n        \r\n    </div>\r\n    \n\n<div class=\"frm_dropzone frm_single_upload frm_clearfix\" id=\"file2418_dropzone\" role=\"group\" >\n	<div class=\"fallback\">\n		<div class=\'input\'></div>\n				<div class=\"frm_clearfix \"></div>\n	</div>\n	<div class=\"dz-message needsclick\">\n		<span class=\"frm_icon_font frm_upload_icon\"></span>\n		<span class=\"frm_upload_text\"><button type=\"button\">Drop a file here or click to upload</button></span>\n		<span class=\"frm_compact_text\"><button type=\"button\">Choose File</button></span>\n		<div class=\"frm_small_text\">\n			Maximum upload size: 20.97MB		</div>\n	</div>\n</div>\n\r\n    \r\n    \r\n</div>\n    </div>\r\n    \r\n  </div>\r\n<div class=\"hide\">[frm-conditions]{\"864\":{\"field_id\":[\"164\"],\"hide_opt\":[\"other\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\"],\"show_hide\":\"show\"},\"217\":{\"field_id\":[\"6351\",\"6351\",\"6351\",\"6351\",\"6351\"],\"hide_opt\":[\"White: Any other White background\",\"Mixed: Any other Mixed background\",\"Asian or Asian British: Any other Asian background\",\"Black or Black British: Any other Black background\",\"Other ethnic group: Any other ethnic group\"],\"any_all\":\"any\",\"hide_field_cond\":[\"==\",\"==\",\"==\",\"==\",\"==\"],\"show_hide\":\"show\"},\"1226\":{\"field_id\":[\"6854\"],\"hi