(15,48,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_48_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_2033_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\"></h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_1078_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Nominated pharmacy details</h3>\r\n\r\n\r\n<div id=\"frm_field_6860_container\" class=\"frm_form_field  hide-item frm_html_container form-field\">\n<p><a href=\"https://www.nhs.uk/service-search/pharmacy/find-a-pharmacy\" target=\"_blank\">Find a local pharmacy</a></p>\n</div>\n<div id=\"frm_field_1079_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Pharmacy Name:\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\'input text\'>[1079]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1080_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Pharmacy Address:\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\'input text\'>[1080]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1081_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_third\">\r\n    <div class=\"frm_label frm_primary_label\">Pharmacy Postcode:\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\'input text\'>[1081]</div>\r\n    \r\n    \r\n</div>\n</div>\n    </div>\r\n    \r\n  </div>\r\n<div class=\"hide\">[frm-conditions]null[/frm-conditions]</div>'),
(16,47,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_47_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_6819_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">Section</h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_1036_container\" class=\"frm_form_field frm_section_heading form-field \">\r\n<h3 class=\"frm_pos_top frm_section_spacing\">During the past 4 weeks</h3>\r\n\r\n\r\n<div id=\"frm_field_1037_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_half vertical_radio\">\r\n    <div  id=\"field_st2pp2_label\" class=\"frm_primary_label\">How would you describe the pain you usually have in your hip?\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_st2pp2_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_1037-1036-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1037]=None - 1].png\'><div class=\"frm_label\">		 None</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1037-1036-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1037]=Very mild - 2].png\'><div class=\"frm_label\">		 Very mild</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1037-1036-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1037]=Mild - 3].png\'><div class=\"frm_label\">		 Mild</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1037-1036-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1037]=Moderate - 4].png\'><div class=\"frm_label\">		 Moderate</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1037-1036-4\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1037]=Severe - 5].png\'><div class=\"frm_label\">		 Severe</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1038_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_half vertical_radio\">\r\n    <div  id=\"field_dgvdr2_label\" class=\"frm_primary_label\">Have you been troubled by pain from your hip in bed at night?\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_dgvdr2_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_1038-1036-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1038]=No nights - 1].png\'><div class=\"frm_label\">		 No nights</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1038-1036-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1038]=Only 1 or 2 nights - 2].png\'><div class=\"frm_label\">		 Only 1 or 2 nights</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1038-1036-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1038]=Some nights - 3].png\'><div class=\"frm_label\">		 Some nights</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1038-1036-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1038]=Most nights - 4].png\'><div class=\"frm_label\">		 Most nights</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1038-1036-4\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1038]=Every night - 5].png\'><div class=\"frm_label\">		 Every night</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1039_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_half vertical_radio\">\r\n    <div  id=\"field_haioz2_label\" class=\"frm_primary_label\">Have you had any sudden, severe pain (shooting, stabbing, or spasms) from your affected hip?\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_haioz2_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_1039-1036-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1039]=No days - 1].png\'><div class=\"frm_label\">		 No days</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1039-1036-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1039]=Only 1 or 2 days - 2].png\'><div class=\"frm_label\">		 Only 1 or 2 days</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1039-1036-2\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1039]=Some days - 3].png\'><div class=\"frm_label\">		 Some days</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1039-1036-3\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1039]=Most days - 4].png\'><div class=\"frm_label\">		 Most days</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1039-1036-4\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1039]=Every day - 5].png\'><div class=\"frm_label\">		 Every day</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_1040_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_half vertical_radio\">\r\n    <div  id=\"field_gpmxa2_label\" class=\"frm_primary_label\">Have you been limping when walking because of your hip?\r\n        <span class=\"frm_required\" aria-hidden=\"true\">*</span>\r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_gpmxa2_label\" role=\"group\">		<div class=\"frm_radio\" id=\"frm_radio_1040-1036-0\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1040]=Rarely/Never - 1].png\'><div class=\"frm_label\">		 Rarely/Never</div></div>\n		<div class=\"frm_radio\" id=\"frm_radio_1040-1036-1\"><img class=\'radio\' src=\'/wp-content/plugins/spForms/images/radio_[[1040]=Sometimes or just at first - 2].png\'><div class=\"frm_label\">		 Sometimes or just at first</div></div>\n		<div class=\"frm_radio\"