(22,17,'  <div class=\"frm_forms with_frm_style\" id=\"frm_form_17_container\">\r\n\r\n    \r\n\r\n    <div class=\"frm_form_fields \">\r\n\r\n      <div id=\"frm_field_2027_container\" class=\"frm_form_field frm_section_heading form-field  sp_patient_identification\">\r\n<h3 class=\"frm_pos_top frm_section_spacing\"></h3>\r\n\r\n\r\n</div>\n<div id=\"frm_field_322_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container\">\r\n    <div class=\"frm_label frm_primary_label\">Address:\r\n        \r\n    </div>\r\n    <div class=\'textarea\' style=\'min-height:77px\'>[322]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6764_container\" class=\"frm_form_field form-field  frm_top_container vertical_radio\">\r\n    <div  id=\"field_h5x3k_label\" class=\"frm_primary_label\">Which online services would you like to access?\r\n        \r\n    </div>\r\n    <div class=\"frm_opt_container\" aria-labelledby=\"field_h5x3k_label\" role=\"group\">		<div class=\"frm_checkbox\" id=\"frm_checkbox_6764-0\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[6764]=Book, change and cancel appointments].png\'><div class=\"frm_label\"> Book, change and cancel appointments</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_6764-1\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[6764]=Request repeat prescriptions].png\'><div class=\"frm_label\"> Request repeat prescriptions</div></div>\n		<div class=\"frm_checkbox\" id=\"frm_checkbox_6764-2\"><img class=\'checkbox\' src=\'/wp-content/plugins/spForms/images/checkbox_[[6764]=Access my full health record].png\'><div class=\"frm_label\"> Access my full health record</div></div>\n</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6827_container\" class=\"frm_form_field  frm_html_container form-field\">\n<p>Before you continue, you need to read and agree to the following statements.</p>\n<ul>\n<li>I have read and understood the information and things to consider about online services</li>\n<li>I will be responsible for the security of the information that I see or download</li>\n<li>If I choose to share my information with anyone else, this is at my own risk</li>\n<li>If I suspect that my account has been accessed by someone without my agreement, I will contact the surgery as soon as possible</li>\n<li>If I see information in my record that is not about me or is inaccurate, I will contact the surgery as soon as possible</li>\n<li>If I think that I may come under pressure to give access to someone else unwillingly, I will contact the surgery as soon as possible</li>\n</ul>\n</div>\n<div id=\"frm_field_6768_container\" class=\"frm_form_field form-field  frm_required_field frm_top_container frm_first frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Signature:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[6768]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_6770_container\" class=\"frm_form_field form-field  frm_top_container frm_half\">\r\n    <div class=\"frm_label frm_primary_label\">Date:\r\n        \r\n    </div>\r\n    <div class=\'input text\'>[6770]</div>\r\n    \r\n    \r\n</div>\n<div id=\"frm_field_2358_container\" class=\"frm_form_field form-field  frm_top_container\">\r\n    <div  id=\"field_h7pfm_label\" class=\"frm_primary_label\">To complete your online services registration, you can upload proof of identity now or give it to the surgery directly. Accepted forms of identification include photographic ID and proof of address.\r\n        \r\n    </div>\r\n    \n\n<div class=\"frm_dropzone frm_single_upload frm_clearfix\" id=\"file2358_dropzone\" role=\"group\" >\n	<div class=\"fallback\">\n		<div class=\'input\'></div>\n				<div class=\"frm_clearfix \"></div>\n	</div>\n	<div class=\"dz-message needsclick\">\n		<span class=\"frm_icon_font frm_upload_icon\"></span>\n		<span class=\"frm_upload_text\"><button type=\"button\">Drop a file here or click to upload</button></span>\n		<span class=\"frm_compact_text\"><button type=\"button\">Choose File</button></span>\n		<div class=\"frm_small_text\">\n			Maximum upload size: 20.97MB		</div>\n	</div>\n</div>\n\r\n    \r\n    \r\n</div>\n    </div>\r\n    \r\n  </div>\r\n<div class=\"hide\">[frm-conditions]null[/frm-conditions]</div>'),
