--
-- Table structure for table `footfallv6_sp_formthread`
--

DROP TABLE IF EXISTS `footfallv6_sp_formthread`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `footfallv6_sp_formthread` (
  `threadid` int(9) NOT NULL AUTO_INCREMENT,
  `threadstring` varchar(25) DEFAULT NULL,
  `formid` int(9) NOT NULL,
  `domain` varchar(50) DEFAULT NULL,
  `destinationdomain` varchar(50) DEFAULT NULL,
  `lockedby` int(9) DEFAULT NULL,
  `lockedstart` datetime DEFAULT NULL,
  `titleinfo` blob DEFAULT NULL,
  `reschedule_reason` text DEFAULT NULL,
  `searchname` int(10) unsigned DEFAULT NULL,
  `search_nhs_number` int(10) unsigned DEFAULT NULL,
  `searchemail` int(10) unsigned DEFAULT NULL,
  `patientdob` int(10) unsigned DEFAULT NULL,
  `threadstatus` enum('new','parked','closed','waiting','replied','timedout','discarded','processed','on_going','confirmed','rejected') DEFAULT NULL,
  `reason` blob DEFAULT NULL,
  `repliable` char(1) NOT NULL DEFAULT '0',
  `allowreply` char(1) NOT NULL DEFAULT '0',
  `accessattempts` int(2) NOT NULL DEFAULT 0,
  `lockedat` datetime DEFAULT NULL,
  `lastupdated` datetime DEFAULT NULL,
  `initiated` datetime DEFAULT NULL,
  `version` int(3) DEFAULT 0,
  `assignedby` int(9) DEFAULT NULL,
  `assignedto` int(9) DEFAULT NULL,
  `assignednote` blob DEFAULT NULL,
  `currenteditor` int(9) DEFAULT NULL,
  `permitpatientreply` char(1) DEFAULT '0',
  `permitfileupload` tinyint(1) NOT NULL DEFAULT 0,
  `assignlimit` datetime DEFAULT NULL,
  `parklimit` datetime DEFAULT NULL,
  `waitlimit` datetime DEFAULT NULL,
  `unreadlimit` datetime DEFAULT NULL,
  `unrepliedlimit` datetime DEFAULT NULL,
  `meshlimit` datetime DEFAULT NULL,
  `urgent` char(1) DEFAULT '0',
  `breachtime` datetime DEFAULT NULL,
  `proxy` tinyint(1) NOT NULL DEFAULT 0,
  `practiceproxyid` int(11) DEFAULT NULL,
  `lastpracticereplyby` int(11) DEFAULT NULL,
  `patient_id` bigint(20) unsigned NOT NULL,
  `statuscheck` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`threadid`),
  KEY `inx2` (`threadstring`),
  KEY `inx3` (`searchname`),
  KEY `inx4` (`searchemail`),
  KEY `inx5` (`patientdob`),
  KEY `inx6` (`threadstatus`),
  KEY `inx7` (`assignedto`),
  KEY `unreadlimit_index` (`unreadlimit`),
  KEY `inx8` (`initiated`),
  KEY `idx_formid` (`formid`),
  KEY `idx_assignedby` (`assignedby`),
  KEY `idx_lastpracticereplyby` (`lastpracticereplyby`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_lastupdated` (`lastupdated`)
) ENGINE=InnoDB AUTO_INCREMENT=222 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

