  `training_confirmed` datetime DEFAULT NULL,
  `training_reminder` datetime DEFAULT NULL,
  `mfa_enabled` tinyint(1) DEFAULT NULL,
  `last_mfa_time` datetime DEFAULT NULL,
  `last_mfa_method` varchar(50) DEFAULT NULL,
  `mfa_sms_code` int(11) DEFAULT NULL,
  `registered_number` varchar(15) DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `user_login_key` (`user_login`),
  KEY `user_nicename` (`user_nicename`),
  KEY `user_email` (`user_email`),
  KEY `users_role_id_foreign` (`role_id`),
