(234,1550569896,1550569896,'new','checkHowGetIPs',75,'37600540d602116f4669f03652f53de6','265a631edb9e65080656f1f89b7fc8ae','Unable to accurately detect IPs','Wordfence was unable to validate a test request to your website. This can happen if your website is behind a proxy that does not use one of the standard ways to convey the IP of the request or it is unreachable publicly. IP blocking and live traffic information may not be accurate. <a href=\"https://www.wordfence.com/help/?query=notice-misconfigured-how-get-ips\" target=\"_blank\" rel=\"noopener noreferrer\">Get More Information</a>','a:0:{}'),
(237,1550569896,1550569896,'new','dnsChange',75,'c1f94b58f4b921454888faa55438db84','788505794ce76f9b2c0a2f5c7ba77142','Your DNS records have changed','We have detected a change in the CNAME records of your DNS configuration for the domain footfallv6.siliconpreview.co.uk. A CNAME record is an alias that is used to point a domain name to another domain name. For example foo.example.com can point to bar.example.com which then points to an IP address of 10.1.1.1. A change in your DNS records may indicate that a hacker has hacked into your DNS administration system and has pointed your email or website to their own server for malicious purposes. It could also indicate that your domain has expired. If you made this change yourself you can mark it \'resolved\' and safely ignore it.','a:4:{s:4:\"type\";s:5:\"CNAME\";s:4:\"host\";s:35:\"footfallv6.siliconpreview.co.uk\";s:6:\"oldDNS\";s:0:\"\";s:6:\"newDNS\";s:72:\"footfallv6.siliconpreview.co.uk points to live.siliconservices.co.uk\";}'),
(240,1550570283,1550570283,'new','wfUpgrade',75,'a3ac687e5d01f6dfa4ec1829aebfd8ee','a3ac687e5d01f6dfa4ec1829aebfd8ee','Your WordPress version is out of date','WordPress version 5.0.3 is now available. Please upgrade immediately to get the latest security updates from WordPress.','a:2:{s:14:\"currentVersion\";s:5:\"4.9.5\";s:10:\"newVersion\";s:5:\"5.0.3\";}'),
(243,1550570283,1550570283,'new','wfPluginUpgrade',50,'4d95cbc142152c0353e372e5a000fb39','4d95cbc142152c0353e372e5a000fb39','The Plugin \"Advanced Custom Fields\" needs an upgrade (4.4.12 -> 5.7.12).','You need to upgrade \"Advanced Custom Fields\" to the newest version to ensure you have any security fixes the developer has released.','a:16:{s:4:\"Name\";s:22:\"Advanced Custom Fields\";s:9:\"PluginURI\";s:36:\"http://www.advancedcustomfields.com/\";s:7:\"Version\";s:6:\"4.4.12\";s:11:\"Description\";s:142:\"Customise WordPress with powerful, professional and intuitive fields <cite>By <a href=\"http://www.elliotcondon.com/\">Elliot Condon</a>.</cite>\";s:6:\"Author\";s:56:\"<a href=\"http://www.elliotcondon.com/\">Elliot Condon</a>\";s:9:\"AuthorURI\";s:28:\"http://www.elliotcondon.com/\";s:10:\"TextDomain\";s:3:\"acf\";s:10:\"DomainPath\";s:5:\"/lang\";s:7:\"Network\";b:0;s:5:\"Title\";s:73:\"<a href=\"http://www.advancedcustomfields.com/\">Advanced Custom Fields</a>\";s:10:\"AuthorName\";s:13:\"Elliot Condon\";s:10:\"pluginFile\";s:99:\"/sync/apache/sitedata/footfall/footfallv6/www/wp-content/plugins/advanced-custom-fields/acf.php\";s:10:\"newVersion\";s:6:\"5.7.12\";s:4:\"slug\";s:22:\"advanced-custom-fields\";s:5:\"wpURL\";s:52:\"https://wordpress.org/plugins/advanced-custom-fields\";s:10:\"vulnerable\";b:0;}'),
(246,1550570283,1550570283,'new','wfPluginUpgrade',50,'76908969274a93905bfa8cbd22471e1e','76908969274a93905bfa8cbd22471e1e','The Plugin \"CMS Tree Page View\" needs an upgrade (1.5 -> 1.6).','You need to upgrade \"CMS Tree Page View\" to the newest version to ensure you have any security fixes the developer has released.','a:16:{s:4:\"Name\";s:18:\"CMS Tree Page View\";s:9:\"PluginURI\";s:54:\"http://eskapism.se/code-playground/cms-tree-page-view/\";s:7:\"Version\";s:3:\"1.5\";s:11:\"Description\";s:379:\"Adds a CMS-like tree view of all your pages, like the view often found in a page-focused CMS. Use the tree view to edit, view, add pages and search pages (very useful if you have many pages). And with drag and drop you can rearrange the order of your pages. Page management won&#8217;t get any easier than this! <cite>By <a href=\"http://eskapism.se/\">PÃ¤r ThernstrÃ¶m</a>.</cite>\";s:6:\"Author\";s:50:\"<a href=\"http://eskapism.se/\">PÃ¤r ThernstrÃ¶m</a>\";s:9:\"AuthorURI\";s:19:\"http://eskapism.se/\";s:10:\"TextDomain\";s:18:\"cms-tree-page-view\";s:10:\"DomainPath\";s:11:\"/languages/\";s:7:\"Network\";b:0;s:5:\"Title\";s:87:\"<a href=\"http://eskapism.se/code-playground/cms-tree-page-view/\">CMS Tree Page View</a>\";s:10:\"AuthorName\";s:16:\"PÃ¤r ThernstrÃ¶m\";s:10:\"pluginFile\";s:97:\"/sync/apache/sitedata/footfall/footfallv6/www/wp-content/plugins/cms-tree-page-view/index.php\";s:10:\"newVersion\";s:3:\"1.6\";s:4:\"slug\";s:18:\"cms-tree-page-view\";s:5:\"wpURL\";s:48:\"https://wordpress.org/plugins/cms-tree-page-view\";s:10:\"vulnerable\";b:0;}'),
(249,1550570283,1550570283,'new','wfPluginUpgrade',50,'d5674dd820560a737f01efbec88957ea','d5674dd820560a737f01efbec88957ea','The Plugin \"Formidable Forms\" needs an upgrade (3.01.02 -> 3.06).','You need to upgrade \"Formidable Forms\" to the newest version to ensure you have any security fixes the developer has released.','a:16:{s:4:\"Name\";s:16:\"Formidable Forms\";s:9:\"PluginURI\";s:28:\"https://formidableforms.com/\";s:7:\"Version\";s:7:\"3.01.02\";s:11:\"Description\";s:116:\"Quickly and easily create drag-and-drop forms <cite>By <a href=\"https://formidableforms.com/\">Strategy11</a>.</cite>\";s:6:\"Author\";s:53:\"<a href=\"https://formidableforms.com/\">Strategy11</a>\";s:9:\"AuthorURI\";s:28:\"https://formidableforms.com/\";s:10:\"TextDomain\";s:10:\"formidable\";s:10:\"DomainPath\";s:0:\"\";s:7:\"Network\";b:0;s:5:\"Title\";s:59:\"<a href=\"https://formidableforms.com/\">Formidable Forms</a>\";s:10:\"AuthorName\";s:10:\"Strategy11\";s:10:\"pluginFile\";s:94:\"/sync/apache/sitedata/footfall/footfallv6/www/wp-content/plugins/formidable/formidable.php\";s:10:\"newVersion\";s:4:\"3.06\";s:4:\"slug\";s:10:\"formidable\";s:5:\"wpURL\";s:65:\"https://formidableforms.com/downloads/formidable-pro/?changelog=1\";s:10:\"vulnerable\";b:0;}'),
(252,1550570283,1550570283,'new','wfPluginUpgrade',50,'573036e8d47b2eb18e091db2f93c5255','573036e8d47b2eb18e091db2f93c5255','The Plugin \"ManageWP - Worker\" needs an upgrade (4.6.3 -> 4.6.6).','You need to upgrade \"ManageWP - Worker\" to the newest version to ensure you have any security fixes the developer has released.','a:16:{s:4:\"Name\";s:17:\"ManageWP - Worker\";s:9:\"PluginURI\";s:20:\"https://managewp.com\";s:7:\"Version\";s:5:\"4.6.3\";s:11:\"Description\";s:498:\"We help you efficiently manage all your WordPress websites. <strong>Updates, backups, 1-click login, migrations, security</strong> and more, on one dashboard. This service comes in two versions: standalone <a href=\"https://managewp.com\">ManageWP</a> service that focuses on website management, and <a href=\"https://godaddy.com/pro\">GoDaddy Pro</a> that includes additional tools for hosting, client management, lead generation, and more. <cite>By <a href=\"https://managewp.com\">ManageWP</a>.</cite>\";s:6:\"Author\";s:43:\"<a href=\"https://managewp.com\">ManageWP</a>\";s:9:\"AuthorURI\";s:20:\"https://managewp.com\";s:10:\"TextDomain\";s:6:\"worker\";s:10:\"DomainPath\";s:0:\"\";s:7:\"Network\";b:1;s:5:\"Title\";s:52:\"<a href=\"https://managewp.com\">ManageWP - Worker</a>\";s:10:\"AuthorName\";s:8:\"ManageWP\";s:10:\"pluginFile\";s:84:\"/sync/apache/sitedata/footfall/footfallv6/www/wp-content/plugins/worker/init.php\";s:10:\"newVersion\";s:5:\"4.6.6\";s:4:\"slug\";s:6:\"worker\";s:5:\"wpURL\";s:36:\"https://wordpress.org/plugins/worker\";s:10:\"vulnerable\";b:0;}'),
