Page\", \"genre\": \"condition\", \"datePublished\": \"2017-10-23T14:04:20+00:00\", \"dateModified\": \"2020-02-21T15:23:50+00:00\", \"lastReviewed\": [\"2017-12-19T00:00:00+00:00\", \"2020-12-19T00:00:00+00:00\"], \"reviewDue\": \"2020-12-19T00:00:00+00:00\", \"keywords\": [\"Nosebleeds\", \"Hypertension\"], \"code\": [{\"@type\": \"MedicalCode\", \"codeValue\": \"\", \"codingSystem\": \"SNOMED-CT\"}]}, \"url\": \"https://api.nhs.uk/conditions/nosebleed/\", \"name\": \"Nosebleed\"}, {\"description\": \"The NHS Health Check is a health check-up for adults in England aged 40 to 74.\", \"linkRelationship\": \"Result\", \"@type\": \"LinkRole\", \"articleStatus\": \"published\", \"mainEntityOfPage\": {\"@type\": \"MedicalWebPage\", \"genre\": \"guide\", \"datePublished\": \"2017-12-21T18:28:14+00:00\", \"dateModified\": \"2020-01-29T11:17:12+00:00\", \"lastReviewed\": [\"2019-11-26T00:00:00+00:00\", \"2022-11-26T00:00:00+00:00\"], \"reviewDue\": \"2022-11-26T00:00:00+00:00\", \"code\": [{\"@type\": \"MedicalCode\", \"codeValue\": \"\", \"codingSystem\": \"SNOMED-CT\"}]}, \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/\", \"name\": \"NHS Health Check\"}, {\"description\": \"Find out about the different types of screening offered by the NHS in England.\", \"linkRelationship\": \"Result\", \"@type\": \"LinkRole\", \"articleStatus\": \"published\", \"mainEntityOfPage\": {\"@type\": \"MedicalWebPage\", \"genre\": \"condition\", \"datePublished\": \"2018-04-09T12:00:30+00:00\", \"dateModified\": \"2020-08-18T16:59:19+00:00\", \"lastReviewed\": [\"2018-05-14T12:20:00+00:00\", \"2021-05-14T12:20:00+00:00\"], \"reviewDue\": \"2021-05-14T12:20:00+00:00\", \"keywords\": [], \"code\": [{\"@type\": \"MedicalCode\", \"codeValue\": \"\", \"codingSystem\": \"SNOMED-CT\"}]}, \"url\": \"https://api.nhs.uk/conditions/nhs-screening/\", \"name\": \"NHS screening\"}]}'),
(6,'2020-09-11','conditions_nhs_health_check','{\"@context\": \"http://schema.org\", \"@type\": \"MedicalWebPage\", \"name\": \"NHS Health Check\", \"copyrightHolder\": {\"name\": \"Crown Copyright\", \"@type\": \"Organization\"}, \"license\": \"https://developer.api.nhs.uk/terms\", \"author\": {\"url\": \"https://www.nhs.uk\", \"logo\": \"https://www.nhs.uk/nhscwebservices/documents/logo1.jpg\", \"email\": \"nhswebsite.servicedesk@nhs.net\", \"@type\": \"Organization\", \"name\": \"NHS website\"}, \"about\": {\"@type\": \"WebPage\", \"name\": \"NHS Health Check\"}, \"description\": \"The NHS Health Check is a health check-up for adults in England aged 40 to 74.\", \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/\", \"lastReviewed\": [\"2019-11-26T00:00:00+00:00\", \"2022-11-26T00:00:00+00:00\"], \"breadcrumb\": {\"@context\": \"http://schema.org\", \"@type\": \"BreadcrumbList\", \"itemListElement\": [{\"@type\": \"ListItem\", \"position\": 0, \"item\": {\"@id\": \"https://api.nhs.uk/conditions/\", \"name\": \"Health A to Z\", \"genre\": \"condition\"}}, {\"@type\": \"ListItem\", \"position\": 1, \"item\": {\"@id\": \"https://api.nhs.uk/conditions/nhs-health-check/\", \"name\": \"NHS Health Check\", \"genre\": \"guide\"}}]}, \"dateModified\": \"2020-01-29T11:17:12+00:00\", \"genre\": \"guide\", \"relatedLink\": [{\"position\": 0, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"Menu\", \"relatedLink\": [{\"position\": 0, \"linkRelationship\": \"Featured\", \"@type\": \"LinkRole\", \"name\": \"FeaturedBox\", \"relatedLink\": [{\"position\": 0, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"Look up NHS Health Check in your area\", \"url\": \"https://www.nhs.uk/Service-Search/NHS-Health-Check/LocationSearch/1891\"}, {\"position\": 1, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"Healthy lifestyle support\", \"url\": \"https://www.nhs.uk/livewell/Pages/Livewellhub.aspx\"}]}, {\"position\": 1, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"What is it?\", \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/what-is-an-nhs-health-check-new/\"}, {\"position\": 2, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"How to get one\", \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/nhs-health-check/\"}, {\"position\": 3, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"What to expect\", \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/what-happens-at-an-nhs-health-check-new/\"}, {\"position\": 4, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"Pros and cons\", \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/pros-and-cons-of-the-nhs-health-check/\"}, {\"position\": 5, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"Your action plan\", \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/your-nhs-health-check-results-and-action-plan/\"}, {\"position\": 6, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"Apps and trackers\", \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/tools-and-technology-that-can-help/\"}, {\"position\": 7, \"linkRelationship\": \"Navigation\", \"@type\": \"LinkRole\", \"name\": \"What\'s your heart age?\", \"url\": \"https://api.nhs.uk/conditions/nhs-health-check/check-your-heart-age-tool/\"}]}], \"mainEntityOfPage\": [{\"identifier\": \"0\", \"name\": \"section heading\", \"position\": 0, \"@type\": \"WebPageElement\", \"text\": \"\", \"mainEntityOfPage\": [{\"position\": 0, \"identifier\": \"1\", \"text\": \"<h2><a href=\\\"https://api.nhs.uk/conditions/nhs-health-check/what-is-an-nhs-health-check-new/\\\">What is an NHS Health Check?</a></h2><p>The <a href=\\\"https://api.nhs.uk/conditions/nhs-health-check/what-is-an-nhs-health-check-new/\\\">NHS Health Check</a> is a health check-up for adults in England aged 40 to 74. It&#x27;s designed to spot early signs of stroke, kidney disease, heart disease, type 2 diabetes or dementia. As we get older, we have a higher risk of developing one of these conditions. An NHS Health Check helps find ways to lower this risk.</p><h2><a href=\\\"https://api.nhs.uk/conditions/nhs-health-check/nhs-health-check/\\\">Am I eligible for an NHS Health Check?</a></h2><p>The check is for people who are aged 40 to 74 who do not have any of the following pre-existing conditions:</p><ul><li>heart disease</li><li>chronic kidney disease</li><li>diabetes</li><li>high blood pressure (hypertension)</li><li>atrial fibrillation</li><li>transient ischaemic attack</li><li>inherited high cholesterol (familial hypercholesterolemia)</li><li>heart failure</li><li>peripheral arterial disease</li><li>stroke</li><li>currently being prescribed statins to lower cholesterol</li><li>previous checks have found that you have a 20% or higher risk of getting cardiovascular disease over the next 10 years</li></ul><h2><a href=\\\"https://api.nhs.uk/conditions/nhs-health-check/nhs-health-check/\\\">How do I get an NHS Health Check?</a></h2><p>If you&#x27;re in the 40 to 74 age group without a pre-existing condition, you should receive a letter from your GP surgery or local council inviting you for a free NHS Health Check every 5 years. You can also call your GP surgery to book a Health Check. You may want to try this online <a href=\\\"https://api.nhs.uk/conditions/nhs-health-check/check-your-heart-age-tool/\\\">Heart Age test</a>.</p><h2><a href=\\\"https://api.nhs.uk/conditions/nhs-health-check/your-nhs-health-check-results-and-action-plan/\\\">How can I improve my test results?</a></h2><p>Once you&#x27;ve had your NHS Health Check, your healthcare professional will <a href=\\\"https://api.nhs.uk/conditions/nhs-health-check/your-nhs-health-check-results-and-action-plan/\\\">discuss your results with you</a>. You&#x27;ll be given advice to help you lower your risk of a stroke, kidney disease, heart disease, diabetes or dementia, and maintain or improve your health. But you do not have to wait until then to make healthy changes. Take the <a href=\\\"/oneyou/hay#EgH2JmspGQv5Ldyf.97\\\">How Are You quiz</a> and start now with these <a href=\\\"https://api.nhs.uk/conditions/nhs-health-check/tools-and-technology-that-can-help/\\\">health apps and trackers</a>.</p>\", \"@type\": \"WebPageElement\", \"name\": \"markdown\"}]}]}'),
